pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import { RolesAwareUpgradeable } from "../extensions/Roles/RolesAwareUpgradeable.sol";
import { IFundingPool } from "../interfaces/IFundingPool.sol";
import { IIdeaRegistry } from "../interfaces/IIdeaRegistry.sol";
import { ICommunityFactoryRegistry } from "../interfaces/ICommunityFactoryRegistry.sol";
import { IProtocolRevenueTreasury } from "../interfaces/IProtocolRevenueTreasury.sol";
import "../utils/Errors.sol";

/**
 * @title FundingPool
 * @notice Manages USDC deposits and distributes grants to winning ideas
 * @dev Handles donor balances, fund safekeeping, and controlled distribution
 * @dev Pausable, Upgradeable. Revenue is disabled by default and snapshotted only
 *      for newly opened rounds; old reserves and Community inflows are not revenue.
 * 
 * @custom:version 2.0.0
 */
contract FundingPoolUpgradeable is 
    Initializable, 
    ReentrancyGuardUpgradeable, 
    PausableUpgradeable, 
    RolesAwareUpgradeable, 
    IFundingPool 
{
    using SafeERC20 for IERC20;

    /* ========== CONTRACTS ========== */ 

    /// @notice USDC contract used for all treasury flows
    IERC20 public usdc;

    /// @notice IdeaRegistry contract address for author verification
    IIdeaRegistry public ideaRegistry;

    /* ========== STATE VARIABLES ========== */

    /// @notice Total tokens held in the pool
    uint256 public totalPoolBalance;

    /// @notice Protocol reserve retained after distributions
    uint256 public protocolReserve;

    /* ========== STRUCTS ========== */

    /**
     * @notice Structure representing a fund distribution record
     * @param roundId Identifier of the funding round
     * @param ideaId Identifier of the winning idea
     * @param amount Amount of tokens distributed
     * @param distributedAt Timestamp when distribution occurred
     */
    struct Distribution {
        uint256 roundId;
        uint256 ideaId;
        uint256 amount;
        uint256 distributedAt;
    }

    /* ========== STORAGE ========== */

    /// @notice Mapping from donor address to their deposited amount
    mapping(address => uint256) public donorBalances;

    /// @notice Mapping of pool history for Round & ideas: roundId => ideaId => amount
    mapping(uint256 => mapping(uint256 => uint256)) public _poolByRoundAndIdea;

    /// @dev Array of all historical distributions
    Distribution[] public distributionHistory;

    /// @dev Mapping from round ID to distribution status
    mapping(uint256 => bool) public distributed;

    /// @notice Mapping from idea ID to locked author stake amount
    /// @dev Tracks per-idea author deposits in 6-decimal USDC units.
    mapping(uint256 => uint256) public authorStakeByIdea;

    /// @notice BERT V3 Factory authorized to authenticate CommunityTreasury reserve inflows
    address public communityFactory;

    /// @dev Individual pledge data is deliberately separate from donor balances.
    struct Pledge {
        uint256 ideaId;
        uint256 amount;
        bool refundClaimed;
    }

    /// @notice Pledge fee in basis points, charged only when a round funds a winner.
    uint256 public pledgeFeeBps;

    /// @notice Funding-round lifecycle and selected winner.
    mapping(uint256 => bool) public fundingRoundOpened;
    mapping(uint256 => bool) public fundingRoundSettled;
    mapping(uint256 => uint256) public fundingRoundWinner;

    /// @notice Immutable fee snapshots, one per opened funding round.
    mapping(uint256 => uint256) public fundingRoundFeeBps;

    /// @notice One wallet may have exactly one refundable pledge in one funding round.
    mapping(uint256 => mapping(address => Pledge)) private pledges;

    /// @notice Fee held in escrow until the winning author actually starts the grant.
    mapping(uint256 => uint256) public pendingProtocolFeeByRound;
    mapping(uint256 => bool) public fundingRoundFeeFinalized;
    mapping(uint256 => bool) public fundingRoundCancelled;
    mapping(uint256 => bool) public grantRefundActive;
    mapping(uint256 => uint256) public winningGrossPledgeByRound;
    mapping(uint256 => uint256) public winningPledgeCountByRound;
    mapping(uint256 => uint256) public grantRefundTotalByRound;
    mapping(uint256 => uint256) public grantRefundPaidByRound;
    mapping(uint256 => uint256) public grantRefundClaimCountByRound;
    mapping(uint256 => mapping(uint256 => uint256)) private _pledgeCountByRoundAndIdea;

    /// @notice V2.3 fee accounting. Fees vest only as the matching grant tranches are released.
    mapping(uint256 => bool) public progressiveFundingRoundFeeStarted;
    mapping(uint256 => uint256) public progressiveFeeReleasedByRound;
    mapping(uint256 => uint256) public progressiveFeeTrancheBpsByRound;
    mapping(uint256 => bool) public progressiveFeeRestoredForRefund;

    /// @notice Factories explicitly allowed to authenticate active CommunityTreasury reserve callers.
    /// @dev Appended for the V3.1 release. It preserves legacy proxy storage and allows V3.0
    ///      and V3.1 Factories to coexist without replacing each other's reserve-routing access.
    mapping(address => bool) public approvedCommunityFactories;

    /// @dev Enumerable allowlist required to authenticate a Treasury against each approved Factory.
    ///      The list is deliberately capped because `receiveCommunityReserve` checks it onchain.
    address[] private approvedCommunityFactoryList;

    /// @notice Maximum Factory count permitted for CommunityTreasury reserve authentication.
    uint256 public constant MAX_COMMUNITY_FACTORIES = 16;

    /// @notice Minimum public notice before a revenue policy affects future rounds.
    uint256 public constant REVENUE_POLICY_DELAY = 48 hours;

    /// @notice Token permanently pinned when a valid revenue policy is first scheduled.
    address public revenueAsset;

    /// @notice Current receiver used only when snapshotting a newly opened round.
    address public revenueTreasury;

    /// @notice Share of earned success fees assigned to that receiver, not a new pledge fee.
    uint256 public revenueShareBps;

    /// @notice Receiver proposed for the next policy; zero is allowed only with zero share.
    address public scheduledRevenueTreasury;

    /// @notice Proposed share of earned fees in basis points.
    uint256 public scheduledRevenueShareBps;

    /// @notice Earliest execution timestamp; zero means no scheduled policy exists.
    uint256 public revenuePolicyReadyAt;

    /**
     * @notice Immutable round policy and cumulative earned Treasury entitlement.
     * @param treasury Receiver fixed when the round opens.
     * @param shareBps Share of earned fees, using a 10,000 denominator.
     * @param accrued Cumulative entitlement including amounts already collected.
     * @param eligibleFee Fee attributable to recorded winning pledges, excluding reserve top-ups.
     * @param totalFee Total fee fixed by the existing settlement logic.
     */
    struct RoundRevenue {
        address treasury;
        uint256 shareBps;
        uint256 accrued;
        uint256 eligibleFee;
        uint256 totalFee;
    }

    /// @notice Policy snapshots; pre-upgrade rounds have zero share and remain unchanged.
    mapping(uint256 => RoundRevenue) public fundingRoundRevenue;

    /// @notice Earned, unpaid entitlement payable exclusively to each receiver.
    mapping(address => uint256) public pendingRevenueByTreasury;

    /// @notice Total earned revenue earmarked outside protocolReserve but still held here.
    uint256 public totalPendingProtocolRevenue;

    /// @notice Actual pledge principal recorded for revenue-enabled round/idea pairs.
    /// @dev Reserve allocation never increases this source-specific counter.
    mapping(uint256 => mapping(uint256 => uint256)) public revenueEligiblePledges;

    /* ========== INITIALIZE ========== */

    constructor() {
        _disableInitializers();
    }

    /**
     * @notice Initializes the FundingPool contract
     * @param _usdc USDC contract address
     * @param _ideaRegistry IdeaRegistry contract address
     * @custom:emits FundingPoolInitialized
     * @custom:requires All addresses must be non-zero
     */
    function initialize(
        address _usdc,
        address _ideaRegistry,
        address _rolesRegistry
    ) public initializer {
        __ReentrancyGuard_init();
        __Pausable_init();

        if (_rolesRegistry == address(0)) revert ZeroAddress("rolesRegistry");

        __RolesAware_init(_rolesRegistry);

        // BERT V2 starts with a transparent 5% success fee; each round snapshots it on open.
        pledgeFeeBps = 500;

        if (_usdc == address(0)) revert ZeroAddress("usdc");
        if (_ideaRegistry == address(0)) revert ZeroAddress("ideaRegistry");

        usdc = IERC20(_usdc);
        ideaRegistry = IIdeaRegistry(_ideaRegistry);

        _pause();

        emit FundingPoolInitialized(msg.sender);
    }

    /**
     * @notice Initializes conditional-pledge configuration on an already initialized legacy proxy.
     * @dev `initialize` cannot run during a proxy upgrade, so this one-time migration sets the
     *      first fee used by newly opened rounds without touching existing pool accounting.
     */
    function initializeConditionalPledges(uint256 initialFeeBps) external reinitializer(2) onlyAdmin {
        if (initialFeeBps > 1_000) revert InvalidParameter("initialFeeBps", "above 10 percent");
        pledgeFeeBps = initialFeeBps;
        emit PledgeFeeUpdated(initialFeeBps);
    }

    /**
     * @notice Seeds the V3 Factory allowlist from the legacy configured Factory after upgrade.
     * @dev This one-time migration preserves V3.0 reserve routing before a V3.1 Factory is added.
     *      It may initialize an empty allowlist when no legacy Factory was configured.
     * @custom:emits CommunityFactoryApprovalUpdated
     */
    function initializeCommunityFactoryAllowlist() external reinitializer(3) onlyAdmin {
        if (communityFactory != address(0)) {
            _setCommunityFactoryApproval(communityFactory, true);
        }
    }

    /* ========== EXTERNAL FUNCTIONS ========== */

    /**
     * @notice Deposits USDC into the funding pool
     * @dev Transfers tokens from caller to contract, updates donor balance
     * @param amount Amount of tokens to deposit
     * @custom:emits FundsDeposited
     * @custom:emits PoolBalanceUpdated
     * @custom:requires amount > 0
     * @custom:reentrancy protected
     */
    function deposit(uint256 amount) external nonReentrant whenNotPaused {
        if (amount == 0) {
            revert ZeroAmount();
        }

        usdc.safeTransferFrom(msg.sender, address(this), amount);

        donorBalances[msg.sender] += amount;
        totalPoolBalance += amount;

        emit FundsDeposited(msg.sender, amount);
        emit PoolBalanceUpdated(totalPoolBalance);
    }

    /**
     * @notice Pulls USDC routed by an active BERT V3 CommunityTreasury into protocol reserve
     * @dev Unlike `deposit`, this does not create a donor balance because V3 outcomes are protocol revenue.
     * @param amount Amount of USDC to move from the calling CommunityTreasury
     * @custom:requires At least one V3 Factory allowlisted and caller active in one of them
     */
    function receiveCommunityReserve(uint256 amount) external nonReentrant whenNotPaused {
        if (amount == 0) revert ZeroAmount();
        if (approvedCommunityFactoryList.length == 0) revert CommunityFactoryNotConfigured();
        if (!_isActiveCommunityTreasury(msg.sender)) {
            revert UnauthorizedCommunityTreasury(msg.sender);
        }

        usdc.safeTransferFrom(msg.sender, address(this), amount);
        totalPoolBalance += amount;
        protocolReserve += amount;

        emit CommunityReserveReceived(msg.sender, amount);
        emit PoolBalanceUpdated(totalPoolBalance);
    }

    /**
     * @notice Deposits author stake for a newly created idea
     * @dev Can only be called by the IdeaRegistry contract.
     *      This is separate from voter deposits because the amount is locked
     *      against the idea itself and can later be slashed into `protocolReserve`
     *      if the idea is rejected.
     * @param from Address from which tokens are transferred
     * @param ideaId ID of the idea being created
     * @param amount Amount of tokens to deposit
     */
    function depositAuthorStakeFrom(
        address from,
        uint256 ideaId,
        uint256 amount
    ) external onlyIdeaRegistry nonReentrant {
        if (from == address(0)) {
            revert ZeroAddress("from");
        }
        if (ideaId == 0) {
            revert InvalidId("ideaId");
        }
        if (amount == 0) {
            revert ZeroAmount();
        }

        usdc.safeTransferFrom(from, address(this), amount);

        donorBalances[from] += amount;
        authorStakeByIdea[ideaId] += amount;
        totalPoolBalance += amount;

        emit AuthorStakeDeposited(ideaId, from, amount);
        emit PoolBalanceUpdated(totalPoolBalance);
    }

    /**
     * @notice Opens the escrow ledger for one funding round.
     * @dev The voting system calls this before any user can deposit a pledge.
     */
    function openFundingRound(uint256 roundId) external onlyVotingSystem {
        if (roundId == 0 || fundingRoundOpened[roundId]) revert FundingRoundStateInvalid(roundId);

        fundingRoundOpened[roundId] = true;
        fundingRoundFeeBps[roundId] = pledgeFeeBps;
        fundingRoundRevenue[roundId] = RoundRevenue(revenueTreasury, revenueShareBps, 0, 0, 0);
        emit FundingRoundOpened(roundId, pledgeFeeBps);
        emit FundingRoundRevenueSnapshotted(roundId, revenueTreasury, revenueShareBps);
    }

    /**
     * @notice Pulls and records a refundable pledge made through a funding round.
     */
    function recordPledgeFrom(
        address from,
        uint256 roundId,
        uint256 ideaId,
        uint256 amount
    ) external onlyVotingSystem nonReentrant whenNotPaused {
        if (from == address(0)) revert ZeroAddress("from");
        if (ideaId == 0) revert InvalidId("ideaId");
        if (amount == 0) revert ZeroAmount();
        if (roundId == 0 || !fundingRoundOpened[roundId] || fundingRoundSettled[roundId]) {
            revert FundingRoundStateInvalid(roundId);
        }
        if (pledges[roundId][from].amount != 0) revert FundingRoundStateInvalid(roundId);

        usdc.safeTransferFrom(from, address(this), amount);
        pledges[roundId][from] = Pledge({
            ideaId: ideaId,
            amount: amount,
            refundClaimed: false
        });
        totalPoolBalance += amount;
        _poolByRoundAndIdea[roundId][ideaId] += amount;
        _pledgeCountByRoundAndIdea[roundId][ideaId] += 1;
        if (fundingRoundRevenue[roundId].shareBps != 0) {
            revenueEligiblePledges[roundId][ideaId] += amount;
        }

        emit FundsDeposited(from, amount);
        emit PledgeRecorded(roundId, ideaId, from, amount);
        emit PoolBalanceUpdated(totalPoolBalance);
    }

    /**
     * @notice Settles a funding round, retaining the configured fee only from its winner.
     * @dev A zero winner makes every recorded pledge refundable.
     */
    function settleFundingRound(
        uint256 roundId,
        uint256 winningIdeaId
    ) external onlyVotingSystem nonReentrant {
        if (!fundingRoundOpened[roundId] || fundingRoundSettled[roundId]) {
            revert FundingRoundStateInvalid(roundId);
        }
        fundingRoundSettled[roundId] = true;
        fundingRoundWinner[roundId] = winningIdeaId;

        if (winningIdeaId == 0) {
            emit FundingRoundSettled(roundId, 0, 0, 0, 0);
            return;
        }

        uint256 grossFunding = _poolByRoundAndIdea[roundId][winningIdeaId];
        uint256 fee = (grossFunding * fundingRoundFeeBps[roundId]) / 10_000;
        uint256 netFunding = grossFunding - fee;
        RoundRevenue storage policy = fundingRoundRevenue[roundId];
        if (policy.shareBps != 0) {
            policy.eligibleFee = Math.min(fee, Math.mulDiv(
                revenueEligiblePledges[roundId][winningIdeaId], fundingRoundFeeBps[roundId], 10_000
            ));
            policy.totalFee = fee;
            emit FundingRoundRevenueBaseSet(roundId, policy.eligibleFee, fee);
        }
        _poolByRoundAndIdea[roundId][winningIdeaId] = netFunding;
        pendingProtocolFeeByRound[roundId] = fee;
        winningGrossPledgeByRound[roundId] = grossFunding;
        winningPledgeCountByRound[roundId] = _pledgeCountByRoundAndIdea[roundId][winningIdeaId];
        emit FundingRoundSettled(roundId, winningIdeaId, grossFunding, fee, netFunding);
    }

    /** @notice Finalizes a successful-round fee only after its author claims the grant. */
    function finalizeFundingRoundFee(uint256 roundId) external onlyDistributor nonReentrant {
        uint256 winner = fundingRoundWinner[roundId];
        if (!fundingRoundSettled[roundId] || winner == 0 || fundingRoundCancelled[roundId]) {
            revert FundingRoundStateInvalid(roundId);
        }
        if (fundingRoundFeeFinalized[roundId] || progressiveFundingRoundFeeStarted[roundId]) {
            revert FundingRoundStateInvalid(roundId);
        }

        uint256 fee = pendingProtocolFeeByRound[roundId];
        pendingProtocolFeeByRound[roundId] = 0;
        fundingRoundFeeFinalized[roundId] = true;
        uint256 retained = _accountEarnedFee(roundId, fee, fee);

        emit IdeaFundsReserved(roundId, winner, retained);
        emit FundingRoundFeeFinalized(roundId, fee);
    }

    /**
     * @notice Starts V2.3 progressive fee vesting after the winning author starts their grant.
     * @dev The legacy `finalizeFundingRoundFee` path remains unchanged for V2.2 grants.
     */
    function beginProgressiveFundingRoundFee(uint256 roundId) external onlyDistributor nonReentrant {
        uint256 winner = fundingRoundWinner[roundId];
        if (!fundingRoundSettled[roundId] || winner == 0 || fundingRoundCancelled[roundId]) {
            revert FundingRoundStateInvalid(roundId);
        }
        if (fundingRoundFeeFinalized[roundId] || progressiveFundingRoundFeeStarted[roundId]) {
            revert FundingRoundStateInvalid(roundId);
        }

        progressiveFundingRoundFeeStarted[roundId] = true;
        emit ProgressiveFundingRoundFeeStarted(roundId);
    }

    /**
     * @notice Releases the earned portion of a V2.3 funding-round fee to protocol reserve.
     * @dev `cumulativeTrancheBps` is monotonic. The caller supplies 2,000, 6,000, and
     *      10,000 for the fixed 20/40/40 grant schedule.
     */
    function releaseProgressiveFundingRoundFee(
        uint256 roundId,
        uint256 cumulativeTrancheBps
    ) external onlyDistributor nonReentrant {
        if (
            !progressiveFundingRoundFeeStarted[roundId] ||
            progressiveFeeRestoredForRefund[roundId] ||
            fundingRoundCancelled[roundId] ||
            cumulativeTrancheBps > 10_000 ||
            cumulativeTrancheBps <= progressiveFeeTrancheBpsByRound[roundId]
        ) {
            revert FundingRoundStateInvalid(roundId);
        }

        uint256 totalFee = pendingProtocolFeeByRound[roundId];
        uint256 targetReleased = cumulativeTrancheBps == 10_000
            ? totalFee
            : (totalFee * cumulativeTrancheBps) / 10_000;
        uint256 amount = targetReleased - progressiveFeeReleasedByRound[roundId];

        progressiveFeeTrancheBpsByRound[roundId] = cumulativeTrancheBps;
        progressiveFeeReleasedByRound[roundId] = targetReleased;
        uint256 retained = _accountEarnedFee(roundId, amount, targetReleased);

        if (cumulativeTrancheBps == 10_000) {
            pendingProtocolFeeByRound[roundId] = 0;
            fundingRoundFeeFinalized[roundId] = true;
            emit FundingRoundFeeFinalized(roundId, amount);
        }

        emit IdeaFundsReserved(roundId, fundingRoundWinner[roundId], retained);
        emit FundingRoundFeeReleased(roundId, amount, cumulativeTrancheBps);
    }

    /** @notice Makes a never-claimed winning pledge fully refundable, including its pending fee. */
    function cancelUnclaimedFundingRound(uint256 roundId) external onlyDistributor nonReentrant {
        uint256 winner = fundingRoundWinner[roundId];
        if (
            !fundingRoundSettled[roundId] ||
            winner == 0 ||
            fundingRoundFeeFinalized[roundId] ||
            progressiveFundingRoundFeeStarted[roundId]
        ) {
            revert FundingRoundStateInvalid(roundId);
        }
        if (fundingRoundCancelled[roundId]) revert FundingRoundStateInvalid(roundId);

        uint256 restoredFee = pendingProtocolFeeByRound[roundId];
        pendingProtocolFeeByRound[roundId] = 0;
        fundingRoundCancelled[roundId] = true;
        _poolByRoundAndIdea[roundId][winner] += restoredFee;

        emit FundingRoundCancelled(roundId, winner, restoredFee);
    }

    /** @notice Opens proportional refunds for the unspent portion of an expired live grant. */
    function activateGrantRefund(uint256 roundId) external onlyDistributor nonReentrant {
        uint256 winner = fundingRoundWinner[roundId];
        bool progressive = progressiveFundingRoundFeeStarted[roundId];
        if (
            fundingRoundCancelled[roundId] ||
            winner == 0 ||
            (!progressive && !fundingRoundFeeFinalized[roundId]) ||
            (progressive && progressiveFeeRestoredForRefund[roundId])
        ) {
            revert FundingRoundStateInvalid(roundId);
        }
        if (grantRefundActive[roundId]) revert FundingRoundStateInvalid(roundId);

        if (progressive) {
            uint256 unvestedFee = pendingProtocolFeeByRound[roundId] - progressiveFeeReleasedByRound[roundId];
            pendingProtocolFeeByRound[roundId] = 0;
            progressiveFeeRestoredForRefund[roundId] = true;
            _poolByRoundAndIdea[roundId][winner] += unvestedFee;
            emit UnvestedFundingRoundFeeRestored(roundId, unvestedFee);
        }

        uint256 refundTotal = _poolByRoundAndIdea[roundId][winner];
        grantRefundActive[roundId] = true;
        grantRefundTotalByRound[roundId] = refundTotal;

        emit GrantRefundActivated(roundId, winner, refundTotal);
    }

    /**
     * @notice Returns a losing pledge, a fully cancelled winning pledge, or an expired grant remainder.
     */
    function claimPledgeRefund(uint256 roundId) external nonReentrant whenNotPaused returns (uint256 amount) {
        if (!fundingRoundSettled[roundId]) revert PledgeRefundUnavailable(roundId, msg.sender);

        Pledge storage pledge = pledges[roundId][msg.sender];
        if (pledge.amount == 0) {
            revert PledgeRefundUnavailable(roundId, msg.sender);
        }
        if (pledge.refundClaimed) revert PledgeRefundAlreadyClaimed(roundId, msg.sender);

        uint256 winner = fundingRoundWinner[roundId];
        if (pledge.ideaId == winner) {
            if (fundingRoundCancelled[roundId]) {
                amount = pledge.amount;
            } else if (grantRefundActive[roundId]) {
                uint256 claimantCount = grantRefundClaimCountByRound[roundId] + 1;
                if (claimantCount == winningPledgeCountByRound[roundId]) {
                    amount = grantRefundTotalByRound[roundId] - grantRefundPaidByRound[roundId];
                } else {
                    amount = (grantRefundTotalByRound[roundId] * pledge.amount) / winningGrossPledgeByRound[roundId];
                }
                grantRefundClaimCountByRound[roundId] = claimantCount;
                grantRefundPaidByRound[roundId] += amount;
            } else {
                revert PledgeRefundUnavailable(roundId, msg.sender);
            }
        } else {
            amount = pledge.amount;
        }

        pledge.refundClaimed = true;
        _poolByRoundAndIdea[roundId][pledge.ideaId] -= amount;
        totalPoolBalance -= amount;
        usdc.safeTransfer(msg.sender, amount);

        emit PledgeRefundClaimed(roundId, pledge.ideaId, msg.sender, amount);
        emit PoolBalanceUpdated(totalPoolBalance);
    }

    /// @notice Previews the amount remaining for the author after the configured pledge fee.
    function previewNetFunding(uint256 grossAmount) external view returns (uint256) {
        return grossAmount - ((grossAmount * pledgeFeeBps) / 10_000);
    }

    /// @notice Previews net funding with the fee fixed when this round opened.
    function previewRoundNetFunding(uint256 roundId, uint256 grossAmount) external view returns (uint256) {
        return grossAmount - ((grossAmount * fundingRoundFeeBps[roundId]) / 10_000);
    }

    function getFundingRoundSettlement(uint256 roundId)
        external
        view
        returns (bool opened, bool settled, uint256 winningIdeaId)
    {
        return (fundingRoundOpened[roundId], fundingRoundSettled[roundId], fundingRoundWinner[roundId]);
    }

    function getPledge(uint256 roundId, address voter)
        external
        view
        returns (uint256 ideaId, uint256 amount, bool refundClaimed)
    {
        Pledge storage pledge = pledges[roundId][voter];
        return (pledge.ideaId, pledge.amount, pledge.refundClaimed);
    }

    /* ========== REVENUE FUNCTIONS ========== */

    /**
     * @notice Announces a future-round fee split, without changing any existing round.
     * @param treasury Receiver bound to this proxy and USDC; zero disables revenue.
     * @param shareBps Share of earned fees, at most 10,000; zero requires zero receiver.
     * @dev Replacing a proposal restarts its full delay. Once scheduled, the token
     *      remains pinned even if the proposal is cancelled. A receiver's identity
     *      getters are validation, not proof of trustworthy bytecode.
     */
    function scheduleRevenuePolicy(address treasury, uint256 shareBps) external onlyAdmin {
        _validateRevenuePolicy(treasury, shareBps);
        if (treasury != address(0)) revenueAsset = address(usdc);
        scheduledRevenueTreasury = treasury;
        scheduledRevenueShareBps = shareBps;
        revenuePolicyReadyAt = block.timestamp + REVENUE_POLICY_DELAY;
        emit RevenuePolicyScheduled(treasury, shareBps, revenuePolicyReadyAt);
    }

    /// @notice Cancels a proposed policy without modifying active or round-local rules.
    /// @dev Restricted to protocol administrators; the token pin is not cleared.
    function cancelRevenuePolicy() external onlyAdmin {
        if (revenuePolicyReadyAt == 0) revert RevenuePolicyNotReady();
        delete scheduledRevenueTreasury;
        delete scheduledRevenueShareBps;
        delete revenuePolicyReadyAt;
        emit RevenuePolicyCancelled();
    }

    /// @notice Applies the exact announced policy after its public notice period.
    /// @dev Permissionless execution, including while paused. It never rewrites a round.
    function executeRevenuePolicy() external {
        if (revenuePolicyReadyAt == 0 || block.timestamp < revenuePolicyReadyAt) revert RevenuePolicyNotReady();
        address treasury = scheduledRevenueTreasury;
        uint256 shareBps = scheduledRevenueShareBps;
        _validateRevenuePolicy(treasury, shareBps);
        revenueTreasury = treasury;
        revenueShareBps = shareBps;
        delete scheduledRevenueTreasury;
        delete scheduledRevenueShareBps;
        delete revenuePolicyReadyAt;
        emit RevenuePolicyActivated(treasury, shareBps);
    }

    /**
     * @notice Pays only the calling Treasury's already earned success-fee entitlement.
     * @param amount Amount to transfer to msg.sender, never an arbitrary recipient.
     * @dev Separate pull operation: a failed collection cannot block a grant tranche.
     *      Reserve, grants, bonds, pending fees and donations never mint entitlement.
     */
    function claimProtocolRevenue(uint256 amount) external nonReentrant whenNotPaused {
        if (amount == 0 || amount > pendingRevenueByTreasury[msg.sender]) revert RevenueUnavailable();
        if (protocolReserve + totalPendingProtocolRevenue > totalPoolBalance) revert InvalidRevenueAccounting();
        uint256 actual = usdc.balanceOf(address(this));
        if (actual < totalPoolBalance) revert PoolBalanceShortfall(totalPoolBalance, actual);
        pendingRevenueByTreasury[msg.sender] -= amount;
        totalPendingProtocolRevenue -= amount;
        totalPoolBalance -= amount;
        uint256 beforeBalance = usdc.balanceOf(msg.sender);
        usdc.safeTransfer(msg.sender, amount);
        if (
            usdc.balanceOf(msg.sender) != beforeBalance + amount ||
            usdc.balanceOf(address(this)) != actual - amount
        ) revert UnsupportedRevenueTransfer();
        emit ProtocolRevenueClaimed(msg.sender, amount);
        emit PoolBalanceUpdated(totalPoolBalance);
    }

    /**
     * @notice Reports custody, reserve and revenue without labelling other funds as profit.
     * @return actual Actual pool token balance.
     * @return accounted Total recorded custody, including reserve and earned revenue.
     * @return reserve Protocol reserve, not withdrawable team revenue.
     * @return revenue Earned revenue still payable to immutable round receivers.
     * @return otherFunds Other recorded capital: bonds, pledges, grant/fee escrow and donations.
     * @return surplus Unrecorded direct token transfers, never automatically revenue.
     * @return shortfall Amount by which actual custody is below its recorded total.
     * @dev Historical per-category aggregate counters do not exist; otherFunds must
     *      not be presented as a full breakdown of historical liabilities.
     */
    function getTreasuryAccounting() external view returns (
        uint256 actual, uint256 accounted, uint256 reserve, uint256 revenue,
        uint256 otherFunds, uint256 surplus, uint256 shortfall
    ) {
        actual = usdc.balanceOf(address(this));
        accounted = totalPoolBalance;
        reserve = protocolReserve;
        revenue = totalPendingProtocolRevenue;
        if (reserve + revenue > accounted) revert InvalidRevenueAccounting();
        otherFunds = accounted - reserve - revenue;
        if (actual >= accounted) surplus = actual - accounted;
        else shortfall = accounted - actual;
    }

    /**
     * @dev Allocates only newly earned fees; cumulative rounding makes collection timing irrelevant.
     * @param roundId Round whose policy was fixed before pledges were accepted.
     * @param amount Newly earned fee amount.
     * @param cumulativeFee Total fee earned across this round's released tranches.
     * @return retained Portion of amount remaining in protocol reserve.
     */
    function _accountEarnedFee(uint256 roundId, uint256 amount, uint256 cumulativeFee)
        private returns (uint256 retained)
    {
        RoundRevenue storage policy = fundingRoundRevenue[roundId];
        uint256 eligibleEarnedFee = policy.eligibleFee == 0
            ? 0 : Math.mulDiv(cumulativeFee, policy.eligibleFee, policy.totalFee);
        uint256 cumulativeRevenue = Math.mulDiv(eligibleEarnedFee, policy.shareBps, 10_000);
        uint256 revenue = cumulativeRevenue - policy.accrued;
        policy.accrued = cumulativeRevenue;
        if (revenue != 0) {
            pendingRevenueByTreasury[policy.treasury] += revenue;
            totalPendingProtocolRevenue += revenue;
            emit ProtocolRevenueAccrued(roundId, policy.treasury, revenue);
        }
        retained = amount - revenue;
        protocolReserve += retained;
    }

    /// @dev Checks a proposed receiver without calling it from grant settlement or fee vesting.
    /// @param treasury Proposed receiver; zero must be paired with zero share.
    /// @param shareBps Proposed share of earned fees in basis points.
    function _validateRevenuePolicy(address treasury, uint256 shareBps) private view {
        if (shareBps > 10_000 || (treasury == address(0)) != (shareBps == 0)) revert InvalidRevenuePolicy();
        if (treasury != address(0)) {
            if (
                treasury == address(this) || treasury.code.length == 0 ||
                IProtocolRevenueTreasury(treasury).fundingPool() != address(this) ||
                IProtocolRevenueTreasury(treasury).usdc() != usdc
            ) revert InvalidRevenuePolicy();
        }
    }

    /** @notice Configures the successful-round fee; 10% is the hard safety ceiling. */
    function setPledgeFeeBps(uint256 feeBps) external onlyAdmin {
        if (feeBps > 1_000) revert InvalidParameter("feeBps", "above 10 percent");
        pledgeFeeBps = feeBps;
        emit PledgeFeeUpdated(feeBps);
    }

    /**
     * @notice Distributes funds to a winning idea (only distributor role can call)
     * @dev Transfers tokens to idea author, records distribution
     * @param roundId Grant round identifier
     * @param ideaId Winning idea identifier
     * @param amount Amount to distribute
     * @custom:emits FundsDistributed
     * @custom:emits PoolBalanceUpdated
     * @custom:requires Only addresses with GRANT_ROLE can call
     * @custom:requires round not previously distributed
     * @custom:requires amount > 0 and ≤ pool balance for that idea in the round
     * @custom:reentrancy protected
     */
    function distributeFunds(
        uint256 roundId,
        uint256 ideaId,
        uint256 amount
    ) external 
      onlyDistributor
      nonReentrant 
      whenNotPaused 
    {
        if (amount == 0) {
            revert ZeroAmount();
        }

        address author = ideaRegistry.getIdeaAuthor(ideaId);
        if (author == address(0)) {
            revert InvalidAuthor();
        }

        uint256 available = _poolByRoundAndIdea[roundId][ideaId];
        if (amount > available) {
            revert InsufficientIdeaBalance(roundId, ideaId, available, amount);
        }

        uint256 remaining = available - amount;
        _poolByRoundAndIdea[roundId][ideaId] = remaining;
        totalPoolBalance -= amount;
        if (remaining == 0) {
            distributed[roundId] = true;
        }

        distributionHistory.push(Distribution({
            roundId: roundId,
            ideaId: ideaId,
            amount: amount,
            distributedAt: block.timestamp
        }));

        usdc.safeTransfer(author, amount);

        emit FundsDistributed(roundId, ideaId, amount);
        emit PoolBalanceUpdated(totalPoolBalance);
    }

    /**
     * @notice Slashes an author's stake into protocol reserve
     * @dev Can only be called by the IdeaRegistry contract.
     *      If the stake is already zero, the function exits silently so repeated
     *      rejection handling does not break downstream state transitions.
     * @param ideaId ID of the rejected idea
     */
    function slashAuthorStakeToReserve(uint256 ideaId) external onlyIdeaRegistry {
        if (ideaId == 0) {
            revert InvalidId("ideaId");
        }

        uint256 amount = authorStakeByIdea[ideaId];
        if (amount == 0) {
            return;
        }

        authorStakeByIdea[ideaId] = 0;
        protocolReserve += amount;

        emit AuthorStakeSlashed(ideaId, amount);
    }

    /** @notice Releases the author bond once a winning proposal starts its grant lifecycle. */
    function releaseAuthorStakeToAuthor(uint256 ideaId) external onlyIdeaRegistry nonReentrant {
        uint256 amount = authorStakeByIdea[ideaId];
        if (amount == 0) return;

        address author = ideaRegistry.getIdeaAuthor(ideaId);
        if (author == address(0)) revert InvalidAuthor();

        authorStakeByIdea[ideaId] = 0;
        donorBalances[author] -= amount;
        totalPoolBalance -= amount;
        usdc.safeTransfer(author, amount);
        emit AuthorStakeReleased(ideaId, author, amount);
        emit PoolBalanceUpdated(totalPoolBalance);
    }

    /* ========== VIEW FUNCTIONS ========== */

    /**
     * @notice Returns the total number of distributions made
     * @return count Number of distribution records
     */
    function getDistributionCount() external view returns (uint256) {
        return distributionHistory.length;
    }

    /**
     * @notice Returns distribution details by index
     * @param index Position in distributionHistory array
     * @return roundId Grant round identifier
     * @return ideaId Winning idea identifier
     * @return amount Distributed amount
     * @return distributedAt Distribution timestamp
     * @custom:requires index must be within bounds
     */
    function getDistribution(uint256 index) external view returns (
        uint256 roundId,
        uint256 ideaId,
        uint256 amount,
        uint256 distributedAt
    ) {
        if (index >= distributionHistory.length) {
            revert IndexOutOfBounds();
        }
        Distribution memory d = distributionHistory[index];
        return (d.roundId, d.ideaId, d.amount, d.distributedAt);
    }

    /**
     * @notice Checks if funds have been distributed for a specific round
     * @param roundId The ID of the round to check
     * @return bool True if funds have been distributed for this round, false otherwise
     * @custom:requires roundId > 0
     */
    function isDistributed(uint256 roundId) external view returns (bool) {
        if (roundId == 0) {
            revert InvalidId("roundId");
        }
        return distributed[roundId];
    }

    /**
     * @notice Gets the pool balance for a specific idea in a specific round
     * @param roundId The ID of the round
     * @param ideaId The ID of the idea
     * @return uint256 The amount of tokens allocated to this idea in this round
     * @custom:requires roundId > 0
     * @custom:requires ideaId > 0
     */
    function poolByRoundAndIdea(uint256 roundId, uint256 ideaId) external view returns (uint256) {
        if (roundId == 0) {
            revert InvalidId("roundId");
        }
        if (ideaId == 0) {
            revert InvalidId("ideaId");
        }
        return _poolByRoundAndIdea[roundId][ideaId];
    }

    /* =========== ADMIN FUNCTIONS =========== */

    /**
     * @notice Allocates protocol reserve to a specific round/idea
     * @dev Only callable by the admin
     * @param roundId The ID of the round
     * @param ideaId The ID of the idea
     * @param amount Amount of reserve to allocate
     */
    function allocateReserveToIdea(uint256 roundId, uint256 ideaId, uint256 amount) external onlyAdmin {
        if (roundId == 0) {
            revert InvalidId("roundId");
        }
        if (ideaId == 0) {
            revert InvalidId("ideaId");
        }
        if (amount == 0) {
            revert ZeroAmount();
        }
        if (amount > protocolReserve) {
            revert InsufficientPoolBalance(protocolReserve, amount);
        }

        protocolReserve -= amount;
        _poolByRoundAndIdea[roundId][ideaId] += amount;
        emit ProtocolReserveAllocated(roundId, ideaId, amount);
    }

    /**
     * @notice Returns the deprecated governance-token compatibility getter
     * @dev Older integrations still expect `governanceToken()`, but the protocol
     *      now settles exclusively in USDC.
     */
    function governanceToken() external view returns (IERC20 token) {
        return usdc;
    }

    /**
     * @notice Updates the USDC contract address
     * @dev Can only be called by the contract admin
     * @param _newToken New USDC token address
     * @custom:emits UsdcUpdated
     * @custom:emits GovernanceTokenUpdated
     * @custom:requires _newToken cannot be zero address
     */
    function setUsdc(address _newToken) public onlyAdmin {
        if (_newToken == address(0)) {
            revert ZeroAddress("newToken");
        }
        if (revenueAsset != address(0) && _newToken != revenueAsset) revert RevenueAssetLocked();
        usdc = IERC20(_newToken);
        emit UsdcUpdated(_newToken);
        emit GovernanceTokenUpdated(_newToken);
    }

    /**
     * @notice Deprecated compatibility setter retained for older tooling
     * @param _newToken New USDC token address
     */
    function setGovernanceToken(address _newToken) external onlyAdmin {
        setUsdc(_newToken);
    }

    /**
     * @notice Updates the idea registry contract address
     * @dev Can only be called by the contract admin
     * @param _newRegistry New idea registry address
     * @custom:emits IdeaRegistryUpdated
     * @custom:requires _newRegistry cannot be zero address
     */
    function setIdeaRegistry(address _newRegistry) external onlyAdmin {
        if (_newRegistry == address(0)) {
            revert ZeroAddress("newRegistry");
        }
        ideaRegistry = IIdeaRegistry(_newRegistry);
        emit IdeaRegistryUpdated(_newRegistry);
    }

    /**
     * @notice Records the legacy primary V3 Factory and allows it to authenticate reserve contributors.
     * @dev Retained for ABI compatibility. It never revokes a previously allowlisted Factory;
     *      use `setCommunityFactoryApproval` for explicit additive or revocation changes.
     * @param _communityFactory Factory address for active CommunityTreasury validation.
     * @custom:emits CommunityFactoryUpdated
     * @custom:emits CommunityFactoryApprovalUpdated
     */
    function setCommunityFactory(address _communityFactory) external onlyAdmin {
        if (_communityFactory == address(0)) {
            revert ZeroAddress("communityFactory");
        }

        communityFactory = _communityFactory;
        _setCommunityFactoryApproval(_communityFactory, true);
        emit CommunityFactoryUpdated(_communityFactory);
    }

    /**
     * @notice Adds or revokes a Factory that may authenticate active CommunityTreasury callers.
     * @dev Revocation blocks future reserve transfers from that Factory; it does not modify
     *      historical accounting or any Community Treasury balance.
     * @param factory CommunityFactory registry address.
     * @param approved Whether the Factory may authenticate reserve callers.
     * @custom:emits CommunityFactoryApprovalUpdated
     */
    function setCommunityFactoryApproval(address factory, bool approved) external onlyAdmin {
        if (factory == address(0)) revert ZeroAddress("communityFactory");
        _setCommunityFactoryApproval(factory, approved);
    }

    /**
     * @notice Reports whether a Factory may authenticate CommunityTreasury reserve callers.
     * @param factory CommunityFactory registry address to inspect.
     * @return True when the Factory is explicitly allowlisted.
     */
    function isCommunityFactoryApproved(address factory) external view returns (bool) {
        return approvedCommunityFactories[factory];
    }

    /**
     * @notice Returns the number of Factory addresses retained in the reserve-routing registry.
     * @dev Includes revoked entries so an address can be reapproved without shifting indices.
     */
    function communityFactoryCount() external view returns (uint256) {
        return approvedCommunityFactoryList.length;
    }

    /**
     * @notice Returns a Factory address retained in the reserve-routing registry.
     * @param index Zero-based Factory registry index.
     */
    function communityFactoryAt(uint256 index) external view returns (address) {
        return approvedCommunityFactoryList[index];
    }

    /* ========== INTERNAL FUNCTIONS ========== */

    /**
     * @dev Updates the Factory allowlist while preserving a bounded enumerable registry.
     * @param factory CommunityFactory registry address.
     * @param approved Desired allowlist status.
     */
    function _setCommunityFactoryApproval(address factory, bool approved) internal {
        if (approved && !approvedCommunityFactories[factory]) {
            if (approvedCommunityFactoryList.length >= MAX_COMMUNITY_FACTORIES) {
                revert InvalidParameter("communityFactories", "maximum reached");
            }
            approvedCommunityFactoryList.push(factory);
        }

        approvedCommunityFactories[factory] = approved;
        emit CommunityFactoryApprovalUpdated(factory, approved);
    }

    /**
     * @dev Returns true only when `treasury` is active in an explicitly approved Factory.
     *      A malformed/reverted third-party Factory response is ignored rather than blocking
     *      other approved Factories from authenticating their own Treasury.
     * @param treasury CommunityTreasury caller attempting to route reserve USDC.
     */
    function _isActiveCommunityTreasury(address treasury) internal view returns (bool) {
        uint256 factoryCount = approvedCommunityFactoryList.length;
        for (uint256 i = 0; i < factoryCount; ++i) {
            address factory = approvedCommunityFactoryList[i];
            if (!approvedCommunityFactories[factory]) continue;

            try ICommunityFactoryRegistry(factory).isActiveCommunityTreasury(treasury) returns (bool active) {
                if (active) return true;
            } catch {
                // A revoked, malformed, or temporarily unavailable Factory cannot block another one.
            }
        }

        return false;
    }

    /**
     * @notice Checks real pool balance
     * @dev Can only be called by the contract admin.
     *      Records direct-transfer surplus without subtracting reserve, which is
     *      already included in total custody. Never writes off a token shortfall
     *      or classifies surplus as earned revenue. Old inconsistent sync snapshots
     *      require a separate pre-upgrade reconciliation; this is not a migration.
     */
    function syncBalance() external onlyAdmin nonReentrant {
        uint256 real = usdc.balanceOf(address(this));
        if (real < totalPoolBalance) revert PoolBalanceShortfall(totalPoolBalance, real);
        totalPoolBalance = real;
        emit PoolBalanceUpdated(real);
    }

    /* ========== PAUSE FUNCTIONS ========== */

    /**
     * @notice Emergency pause the voting system
     * @dev Only admin can pause. Stops all critical operations.
     * @custom:requires Only admin can call
     */
    function pause() external onlyAdmin {
        _pause();
    }

    /**
     * @notice Unpause the voting system
     * @dev Only admin can unpause. Resumes normal operations.
     * @custom:requires Only admin can call
     */
    function unpause() external onlyAdmin {
        _unpause();
    }

    /**
     * @notice Check if contract is paused
     * @return bool True if contract is paused
     */
    function isPaused() external view returns (bool) {
        return paused();
    }

    /* ========== UPGRADE SAFETY ========== */

    /**
     * @notice Storage gap for future upgrades
     * @dev Reserved storage space to allow for new variables in upgrades
     * @dev Prevents storage collisions when adding new state variables
     * 
     * @custom:upgrade-safety Reserve slots after newly added variables when upgrading
     * @custom:warning Do not reorder existing storage variables in future versions
     */
    uint256[19] private __gap;
}

