pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import { IGrantManager } from "../interfaces/IGrantManager.sol";
import { IFundingPool } from "../interfaces/IFundingPool.sol";
import { IIdeaRegistry } from "../interfaces/IIdeaRegistry.sol";
import { IVotingSystem } from "../interfaces/IVotingSystem.sol";
import { RolesAwareUpgradeable } from "../extensions/Roles/RolesAwareUpgradeable.sol";
import "../utils/IdeaStatus.sol";
import "../utils/Errors.sol";

/**
 * @title GrantManager
 * @notice Central coordinator for grant rounds, voting, and fund distribution
 * @dev Orchestrates the complete DAO grant lifecycle from creation to funding
 * @dev Pausable, Upgradeable. The VotingSystem's per-round snapshot selects
 *      V2.3 backer-governed 20/40/40 or legacy reviewer-governed 30/40/30.
 *      Payout constants do not occupy storage slots; legacy values remain
 *      executable policy for legacy rounds, not unused storage placeholders.
 * 
 * @custom:version 1.3.0
 */
contract GrantManagerUpgradeable is 
    Initializable, 
    ReentrancyGuardUpgradeable, 
    PausableUpgradeable, 
    RolesAwareUpgradeable, 
    IGrantManager 
{
    /* ========== CONTRACTS ========== */

    /// @notice VotingSystem contract interface
    IVotingSystem public votingSystem;

    /// @notice FundingPool contract interface
    IFundingPool public fundingPool;

    /// @notice IdeaRegistry contract interface
    IIdeaRegistry public ideaRegistry;

    /// @dev Deprecated V2 storage slot retained for proxy-upgrade compatibility.
    ///      The conditional-pledge model uses FundingPool's per-round fee instead.
    uint256 public authorSharePercent;

    /* ========== PAYOUT CONSTANTS ========== */

    /// @notice Initial net-grant percentage for legacy reviewer-governed rounds only.
    /// @dev Selected only when isBackerMilestoneRound(roundId) is false.
    ///      This constant occupies no storage slot; do not change legacy round economics.
    uint256 public constant INITIAL_PAYOUT_PERCENT = 30;

    /// @notice Initial net-grant percentage for V2.3 backer-governed rounds only.
    /// @dev Selected when isBackerMilestoneRound(roundId) is true; later stages use 40/40.
    uint256 public constant BACKER_INITIAL_PAYOUT_PERCENT = 20;

    /// @notice In-process net-grant percentage shared by legacy and V2.3 rounds.
    /// @dev The final tranche is the remaining grant after the selected initial tranche and this 40%.
    uint256 public constant IN_PROCESS_PAYOUT_PERCENT = 40;

    /// @notice Minimum waiting period before a rejected milestone can be submitted again
    /// @dev Applies independently per round and per milestone stage
    uint256 public constant MILESTONE_RESUBMIT_COOLDOWN = 48 hours;

    /// @notice The winning author must start the grant within two weeks of round settlement.
    uint256 public constant GRANT_CLAIM_WINDOW = 14 days;

    /// @notice Stage-one proof must be submitted within 45 days of the initial payout.
    uint256 public constant IN_PROCESS_SUBMISSION_WINDOW = 45 days;

    /// @notice Completion proof must be submitted within 60 days of the stage-one payout.
    uint256 public constant COMPLETION_SUBMISSION_WINDOW = 60 days;

    /// @notice Initial proof review window for legacy reviewers or V2.3 winning backers.
    uint256 public constant MILESTONE_REVIEW_WINDOW = 14 days;

    /// @notice Additional time after a V2.3 non-quorum result before cancellation.
    uint256 public constant BACKER_MILESTONE_GRACE_WINDOW = 7 days;

    uint256 public constant BACKER_MILESTONE_QUORUM_BPS = 4_000;
    uint256 public constant BACKER_MIN_APPROVE_BACKERS = 3;

    /* ========== MILESTONE CONSTANTS ========== */

    /// @notice Milestone identifier for the "project is in active implementation" proof stage
    uint8 public constant IN_PROCESS_STAGE = 1;

    /// @notice Milestone identifier for the "project is fully delivered" proof stage
    uint8 public constant COMPLETION_STAGE = 2;

    /// @notice Legacy reviewer approvals required for the 40% in-process payout.
    /// @dev Not the V2.3 weighted backer review rule; see _finalizeBackerMilestone.
    uint8 public constant IN_PROCESS_APPROVAL_THRESHOLD = 3;

    /// @notice Legacy in-process reviewer-vote cap; not a V2.3 backer-count limit.
    uint8 public constant IN_PROCESS_MAX_REVIEWERS = 5;

    /// @notice Legacy reviewer approvals required for the final legacy 30% payout.
    /// @dev V2.3 completion instead uses weighted backer review and the remaining 40%.
    uint8 public constant COMPLETION_APPROVAL_THRESHOLD = 2;

    /// @notice Legacy completion reviewer-vote cap; not a V2.3 backer-count limit.
    uint8 public constant COMPLETION_MAX_REVIEWERS = 3;

    /* ========== STRUCTS ========== */

    /**
     * @notice Tracks the staged payout state for a funded round
     * @dev Flow:
     *      1. `totalGrant` is set when the author claims the winning round
     *      2. `released` increases after every successful payout tranche
     *      3. boolean flags prevent the same tranche from being paid twice
     * @param ideaId Winning idea for the round
     * @param author Author entitled to receive the grant tranches
     * @param totalGrant Total author-side grant reserved after protocol share is carved out
     * @param released Cumulative amount already transferred to the author
     * @param initialClaimed True once the selected initial payout (V2.3 20%, legacy 30%) has executed
     * @param inProcessPaid True once the 40% in-process milestone payout has been executed
     * @param completionPaid True once the remaining completion payout (V2.3 40%, legacy 30%) has executed
     */
    struct GrantPayout {
        uint256 ideaId;
        address author;
        uint256 totalGrant;
        uint256 released;
        bool initialClaimed;
        bool inProcessPaid;
        bool completionPaid;
        uint256 initialClaimedAt;
        uint256 inProcessPaidAt;
        bool cancelled;
    }

    /**
     * @notice Stores the currently active or most recently settled milestone request for a stage
     * @dev Flow:
     *      1. the author submits a request with proof metadata
     *      2. reviewers cast approvals or rejections until the request resolves
     *      3. the request becomes inactive after approval or rejection
     *      4. `lastRejectedAt` gates resubmission via cooldown enforcement
     * @param requestId Monotonic identifier for submissions on the same round/stage
     * @param metadataURI Off-chain pointer with rich proof payloads
     * @param details Human-readable summary shown to reviewers and indexers
     * @param submittedAt Timestamp when the current request version was created
     * @param lastRejectedAt Timestamp of the latest rejected request for cooldown tracking
     * @param approvals Number of reviewer approvals collected for the active request
     * @param rejections Number of reviewer rejections collected for the active request
     * @param maxReviewers Maximum number of reviewer votes allowed for the stage
     * @param approvalThreshold Number of approvals needed for acceptance
     * @param active Whether this request can still receive votes
     */
    struct MilestoneRequest {
        uint256 requestId;
        string metadataURI;
        string details;
        uint256 submittedAt;
        uint256 lastRejectedAt;
        uint8 approvals;
        uint8 rejections;
        uint8 maxReviewers;
        uint8 approvalThreshold;
        bool active;
    }

    /* ========== STORAGE ========== */

    /// @notice Round-level payout state keyed by voting round ID
    /// @dev roundId => staged payout state
    mapping(uint256 => GrantPayout) private _grantPayouts;

    /// @notice Latest milestone request state for each round and payout stage
    /// @dev roundId => stage => request data
    mapping(uint256 => mapping(uint8 => MilestoneRequest)) private _milestoneRequests;

    /// @notice Tracks whether a reviewer has already voted on a specific milestone request version
    /// @dev keccak(roundId, stage, requestId) => reviewer => voted
    mapping(bytes32 => mapping(address => bool)) private _milestoneVotes;

    struct BackerMilestoneTally {
        uint256 approveWeight;
        uint256 rejectWeight;
        uint256 approveBackerCount;
        uint256 graceDeadline;
    }

    /// @dev keccak(roundId, stage, requestId) => weighted V2.3 vote totals.
    mapping(bytes32 => BackerMilestoneTally) private _backerMilestoneTallies;

    /// @dev 0 = no vote, 1 = reject, 2 = approve. Allows a backer to change position before expiry.
    mapping(bytes32 => mapping(address => uint8)) private _backerMilestonePositions;

    /// @dev keccak(roundId, stage, requestId) => immutable V2.3 proof package hash.
    mapping(bytes32 => bytes32) private _backerMilestoneProofHashes;

    /* ========== INITIALIZE ========== */

    constructor() {
        _disableInitializers();
    }

    /**
     * @notice Initializes the GrantManager contract
     * @dev Sets up the initial contract addresses for the DAO ecosystem
     * @param _votingSystem Address of the VotingSystem contract
     * @param _fundingPool Address of the FundingPool contract
     * @param _ideaRegistry Address of the IdeaRegistry contract
     * @param _rolesRegistry Address of the RolesRegistry contract
     * @custom:emits GrantManagerInitialized
     * @custom:requires All addresses must be non-zero
     */
   function initialize(
        address _votingSystem,
        address _fundingPool,
        address _ideaRegistry,
        address _rolesRegistry
    ) public initializer  {
        __ReentrancyGuard_init();
        __Pausable_init();

        if (_rolesRegistry == address(0)) revert ZeroAddress("rolesRegistry");

        __RolesAware_init(_rolesRegistry);

        if (_votingSystem == address(0)) revert ZeroAddress("votingSystem");
        if (_fundingPool == address(0)) revert ZeroAddress("fundingPool");
        if (_ideaRegistry == address(0)) revert ZeroAddress("ideaRegistry");

        votingSystem = IVotingSystem(_votingSystem);
        fundingPool = IFundingPool(_fundingPool);
        ideaRegistry = IIdeaRegistry(_ideaRegistry);
        authorSharePercent = 95;
        _pause();

        emit GrantManagerInitialized(msg.sender);
    }

    /* ========== EXTERNAL FUNCTIONS ========== */

    /**
     * @notice Claims author grant for a winning idea
     * @dev Distributes funds to the author of the winning idea and updates idea status to Funded
     * @param roundId The ID of the funding round
     * @custom:emits RoundFunded
     * @custom:requires Round must not already have funds distributed
     * @custom:requires Round must be ended
     * @custom:requires Round must have a valid winner (winningIdeaId > 0)
     * @custom:requires Winning idea must be in WonVoting status
     * @custom:requires Winning idea author must be valid (non-zero address)
     * @custom:requires Caller must be the author of the winning idea
     */
    function claimGrant(uint256 roundId) external nonReentrant whenNotPaused {
        GrantPayout storage payout = _grantPayouts[roundId];
        if (payout.initialClaimed || fundingPool.isDistributed(roundId)) {
            revert AlreadyDistributed(roundId);
        }

        (, , , uint256 endTime, , bool ended , , , ) = votingSystem.getRoundInfo(roundId);
        if (!ended) {
            revert RoundNotEnded(roundId);
        }
        uint256 claimDeadline = endTime + GRANT_CLAIM_WINDOW;
        if (block.timestamp >= claimDeadline) revert GrantClaimExpired(roundId, claimDeadline);

        (uint256 winningIdeaId, ) = votingSystem.getRoundWinner(roundId);
        if (winningIdeaId == 0) {
            revert NoWinner(roundId);
        }

        IdeaStatus currentStatus = ideaRegistry.getStatus(winningIdeaId);
        if (currentStatus != IdeaStatus.WonVoting) {
            revert IdeaNotEligible(
                winningIdeaId,
                uint8(IdeaStatus.WonVoting),
                uint8(currentStatus)
            );
        }

        address author = ideaRegistry.getIdeaAuthor(winningIdeaId);
        if (author == address(0)) {
            revert InvalidAuthor();
        }
        if (msg.sender != author) {
            revert NotAuthor(msg.sender, author);
        }

        uint256 totalIdeaStake = fundingPool.poolByRoundAndIdea(roundId, winningIdeaId);
        if (totalIdeaStake == 0) {
            revert NoFundsAllocated(roundId, winningIdeaId);
        }
        uint256 authorAmount = totalIdeaStake;
        bool isBackerGoverned = votingSystem.isBackerMilestoneRound(roundId);
        uint256 initialPayout = (authorAmount * _initialPayoutPercent(isBackerGoverned)) / 100;

        // Record payout state before cross-contract interactions so a future
        // dependency upgrade cannot observe this round as unclaimed mid-flow.
        payout.ideaId = winningIdeaId;
        payout.author = author;
        payout.totalGrant = authorAmount;
        payout.released = initialPayout;
        payout.initialClaimed = true;
        payout.initialClaimedAt = block.timestamp;

        if (isBackerGoverned) {
            try fundingPool.beginProgressiveFundingRoundFee(roundId) {
                // V2.3 earns fees only as matching tranches are released.
            } catch {
                revert ExternalCallFailed("FundingPool", "beginProgressiveFundingRoundFee");
            }
            try fundingPool.releaseProgressiveFundingRoundFee(roundId, 2_000) {
                // Initial 20% tranche vests 20% of the successful-round fee.
            } catch {
                revert ExternalCallFailed("FundingPool", "releaseProgressiveFundingRoundFee");
            }
        } else {
            try fundingPool.finalizeFundingRoundFee(roundId) {
                // V2.2 finalizes the whole fee when the grant lifecycle starts.
            } catch {
                revert ExternalCallFailed("FundingPool", "finalizeFundingRoundFee");
            }
        }

        ideaRegistry.updateStatus(winningIdeaId, IdeaStatus.Funded);

        try fundingPool.distributeFunds(roundId, winningIdeaId, initialPayout) {
            emit RoundFunded(roundId, winningIdeaId, initialPayout);
        } catch {
            revert ExternalCallFailed("FundingPool", "distributeFunds");
        }
    }

    /** @notice Expires an unclaimed grant, restoring the winner's full gross pledge for refund. */
    function expireUnclaimedGrant(uint256 roundId) external nonReentrant whenNotPaused {
        (, , , uint256 endTime, , bool ended , , , ) = votingSystem.getRoundInfo(roundId);
        if (!ended) revert RoundNotEnded(roundId);

        uint256 deadline = endTime + GRANT_CLAIM_WINDOW;
        if (block.timestamp < deadline) revert GrantDeadlineNotReached(roundId, deadline);

        (uint256 winningIdeaId, ) = votingSystem.getRoundWinner(roundId);
        if (winningIdeaId == 0 || _grantPayouts[roundId].initialClaimed) {
            revert GrantCancellationUnavailable(roundId);
        }
        if (ideaRegistry.getStatus(winningIdeaId) != IdeaStatus.WonVoting) {
            revert GrantCancellationUnavailable(roundId);
        }

        try fundingPool.cancelUnclaimedFundingRound(roundId) {
            // The pool restores the pending fee before winner refunds are claimed.
        } catch {
            revert ExternalCallFailed("FundingPool", "cancelUnclaimedFundingRound");
        }
        ideaRegistry.updateStatus(winningIdeaId, IdeaStatus.Cancelled);
        emit UnclaimedGrantExpired(roundId, winningIdeaId, deadline);
    }

    /** @notice Closes a stalled milestone request after its reviewer window has elapsed. */
    function expireMilestoneReview(uint256 roundId, uint8 stage) external nonReentrant whenNotPaused {
        if (votingSystem.isBackerMilestoneRound(roundId)) {
            _finalizeBackerMilestone(roundId, stage);
            return;
        }

        GrantPayout storage payout = _grantPayouts[roundId];
        MilestoneRequest storage request = _milestoneRequests[roundId][stage];
        if (!payout.initialClaimed || !request.active) revert NoActiveMilestoneRequest(roundId, stage);

        uint256 deadline = request.submittedAt + MILESTONE_REVIEW_WINDOW;
        if (block.timestamp < deadline) revert MilestoneReviewDeadlineNotReached(roundId, stage, deadline);

        request.active = false;
        request.lastRejectedAt = block.timestamp;
        emit MilestoneRejected(roundId, payout.ideaId, stage, request.requestId);
        emit MilestoneReviewExpired(roundId, payout.ideaId, stage, request.requestId, deadline);
    }

    /** @notice Cancels an incomplete live grant and opens pro-rata refunds for its unspent net pledge. */
    function cancelExpiredGrant(uint256 roundId) external nonReentrant whenNotPaused {
        GrantPayout storage payout = _grantPayouts[roundId];
        if (!payout.initialClaimed || payout.cancelled || payout.completionPaid) {
            revert GrantCancellationUnavailable(roundId);
        }

        uint8 stage = payout.inProcessPaid ? COMPLETION_STAGE : IN_PROCESS_STAGE;
        uint256 deadline = _milestoneDeadline(payout, stage);
        if (block.timestamp < deadline) revert GrantDeadlineNotReached(roundId, deadline);

        MilestoneRequest storage request = _milestoneRequests[roundId][stage];
        if (request.active) {
            request.active = false;
            request.lastRejectedAt = block.timestamp;
            emit MilestoneRejected(roundId, payout.ideaId, stage, request.requestId);
        }

        payout.cancelled = true;

        try fundingPool.activateGrantRefund(roundId) {
            // Remaining escrow is distributed only to the winning pledge cohort.
        } catch {
            revert ExternalCallFailed("FundingPool", "activateGrantRefund");
        }

        ideaRegistry.updateStatus(payout.ideaId, IdeaStatus.Cancelled);
        emit GrantCancelled(roundId, payout.ideaId, deadline);
    }

    /**
     * @notice Submits proof for the next eligible milestone payout stage
     * @dev The author can only have one active request per stage at a time.
     *      Stage configuration is derived on-chain:
     *      - stage 1 (`IN_PROCESS_STAGE`) => 3 approvals out of max 5 reviewers
     *      - stage 2 (`COMPLETION_STAGE`) => 2 approvals out of max 3 reviewers
     * @param roundId The ID of the funding round
     * @param stage Milestone stage identifier
     * @param metadataURI Off-chain metadata pointer with proof materials
     * @param details Short human-readable summary of the submission
     */
    function submitMilestoneProof(
        uint256 roundId,
        uint8 stage,
        string memory metadataURI,
        string memory details
    ) external nonReentrant whenNotPaused {
        if (votingSystem.isBackerMilestoneRound(roundId)) {
            revert BackerMilestoneVotingRequired(roundId, stage);
        }
        _submitMilestoneProof(roundId, stage, metadataURI, details, bytes32(0), false);
    }

    /**
     * @notice Submits a V2.3 proof package with an immutable content hash.
     * @dev The URI can point to a rich package; the hash prevents its content from being
     *      silently replaced after backers begin reviewing it.
     */
    function submitBackerMilestoneProof(
        uint256 roundId,
        uint8 stage,
        string memory metadataURI,
        string memory details,
        bytes32 proofHash
    ) external nonReentrant whenNotPaused {
        if (!votingSystem.isBackerMilestoneRound(roundId)) {
            revert BackerMilestoneVotingRequired(roundId, stage);
        }
        if (proofHash == bytes32(0)) revert InvalidParameter("proofHash", "zero");
        _submitMilestoneProof(roundId, stage, metadataURI, details, proofHash, true);
    }

    function _submitMilestoneProof(
        uint256 roundId,
        uint8 stage,
        string memory metadataURI,
        string memory details,
        bytes32 proofHash,
        bool isBackerGoverned
    ) internal {
        if (bytes(metadataURI).length == 0) {
            revert ZeroLength("metadataURI");
        }

        GrantPayout storage payout = _grantPayouts[roundId];
        if (!payout.initialClaimed) {
            revert MilestoneNotEligible(roundId, stage);
        }
        if (payout.cancelled) revert GrantCancellationUnavailable(roundId);
        if (msg.sender != payout.author) {
            revert NotAuthor(msg.sender, payout.author);
        }

        MilestoneRequest storage request = _milestoneRequests[roundId][stage];
        if (request.active) {
            revert MilestoneRequestActive(roundId, stage);
        }

        _validateMilestoneSubmission(roundId, stage, payout.ideaId, request.lastRejectedAt);

        request.requestId += 1;
        request.metadataURI = metadataURI;
        request.details = details;
        request.submittedAt = block.timestamp;
        request.approvals = 0;
        request.rejections = 0;
        request.active = true;

        if (isBackerGoverned) {
            // V2.3 counts weighted pledges in separate append-only storage.
            if (request.requestId > 2) revert MilestoneNotEligible(roundId, stage);
            request.maxReviewers = 0;
            request.approvalThreshold = 0;
            _backerMilestoneProofHashes[_backerVoteKey(roundId, stage, request.requestId)] = proofHash;
            emit BackerMilestoneProofHashCommitted(roundId, stage, request.requestId, proofHash);
        } else if (stage == IN_PROCESS_STAGE) {
            request.maxReviewers = IN_PROCESS_MAX_REVIEWERS;
            request.approvalThreshold = IN_PROCESS_APPROVAL_THRESHOLD;
        } else if (stage == COMPLETION_STAGE) {
            request.maxReviewers = COMPLETION_MAX_REVIEWERS;
            request.approvalThreshold = COMPLETION_APPROVAL_THRESHOLD;
        } else {
            revert MilestoneNotEligible(roundId, stage);
        }

        emit MilestoneProofSubmitted(roundId, payout.ideaId, stage, request.requestId);
    }

    /**
     * @notice Reviews the active milestone proof request for a round
     * @dev Any address with `REVIEWER_ROLE` may participate until the reviewer cap is reached.
     *      The request resolves as soon as:
     *      - approvals reach the configured threshold, or
     *      - rejections make approval mathematically impossible, or
     *      - the reviewer cap is exhausted
     * @param roundId The ID of the funding round
     * @param stage Milestone stage identifier
     * @param approved True to approve the request, false to reject
     */
    function reviewMilestoneProof(
        uint256 roundId,
        uint8 stage,
        bool approved
    ) external nonReentrant whenNotPaused {
        if (votingSystem.isBackerMilestoneRound(roundId)) {
            revert BackerMilestoneVotingRequired(roundId, stage);
        }
        if (!roles.hasRole(roles.REVIEWER_ROLE(), msg.sender)) {
            revert NotReviewer();
        }

        GrantPayout storage payout = _grantPayouts[roundId];
        if (!payout.initialClaimed) {
            revert MilestoneNotEligible(roundId, stage);
        }
        if (payout.cancelled) revert GrantCancellationUnavailable(roundId);
        if (msg.sender == payout.author) {
            revert CannotReviewOwnIdea(payout.author);
        }

        MilestoneRequest storage request = _milestoneRequests[roundId][stage];
        if (!request.active) {
            revert NoActiveMilestoneRequest(roundId, stage);
        }

        uint256 reviewDeadline = request.submittedAt + MILESTONE_REVIEW_WINDOW;
        if (block.timestamp >= reviewDeadline) {
            revert MilestoneReviewWindowElapsed(roundId, stage, reviewDeadline);
        }

        if (request.approvals + request.rejections >= request.maxReviewers) {
            revert ReviewerLimitReached(roundId, stage, request.maxReviewers);
        }

        bytes32 voteKey = keccak256(abi.encodePacked(roundId, stage, request.requestId));
        if (_milestoneVotes[voteKey][msg.sender]) {
            revert MilestoneAlreadyReviewed(roundId, stage, msg.sender);
        }

        _milestoneVotes[voteKey][msg.sender] = true;

        if (approved) {
            request.approvals += 1;
        } else {
            request.rejections += 1;
        }

        emit MilestoneReviewed(roundId, stage, msg.sender, approved);

        if (request.approvals >= request.approvalThreshold) {
            _approveMilestone(roundId, stage, payout, request);
            return;
        }

        uint8 rejectionThreshold = request.maxReviewers - request.approvalThreshold + 1;
        if (
            request.rejections >= rejectionThreshold ||
            request.approvals + request.rejections >= request.maxReviewers
        ) {
            request.active = false;
            request.lastRejectedAt = block.timestamp;
            emit MilestoneRejected(roundId, payout.ideaId, stage, request.requestId);
        }
    }

    /**
     * @notice Casts or changes a weighted vote on a V2.3 milestone request.
     * @dev Only the immutable winning pledge cohort can vote. Weight comes from the
     *      FundingPool pledge record, not from a caller-supplied value.
     */
    function castBackerMilestoneVote(
        uint256 roundId,
        uint8 stage,
        bool approved
    ) external nonReentrant whenNotPaused {
        if (!votingSystem.isBackerMilestoneRound(roundId)) {
            revert BackerMilestoneVotingRequired(roundId, stage);
        }

        GrantPayout storage payout = _grantPayouts[roundId];
        MilestoneRequest storage request = _milestoneRequests[roundId][stage];
        if (!payout.initialClaimed || payout.cancelled || !request.active) {
            revert NoActiveMilestoneRequest(roundId, stage);
        }

        uint256 deadline = request.submittedAt + MILESTONE_REVIEW_WINDOW;
        if (block.timestamp >= deadline) {
            revert MilestoneReviewWindowElapsed(roundId, stage, deadline);
        }
        if (msg.sender == payout.author) revert CannotReviewOwnIdea(payout.author);

        (uint256 pledgedIdeaId, uint256 weight,) = fundingPool.getPledge(roundId, msg.sender);
        if (pledgedIdeaId != payout.ideaId || weight == 0) {
            revert BackerMilestoneVoteUnavailable(roundId, stage, msg.sender);
        }

        bytes32 voteKey = _backerVoteKey(roundId, stage, request.requestId);
        uint8 nextPosition = approved ? 2 : 1;
        uint8 previousPosition = _backerMilestonePositions[voteKey][msg.sender];
        if (previousPosition == nextPosition) {
            revert BackerMilestoneVoteUnchanged(roundId, stage, msg.sender);
        }

        BackerMilestoneTally storage tally = _backerMilestoneTallies[voteKey];
        if (previousPosition == 2) {
            tally.approveWeight -= weight;
            tally.approveBackerCount -= 1;
        } else if (previousPosition == 1) {
            tally.rejectWeight -= weight;
        }

        if (nextPosition == 2) {
            tally.approveWeight += weight;
            tally.approveBackerCount += 1;
        } else {
            tally.rejectWeight += weight;
        }
        _backerMilestonePositions[voteKey][msg.sender] = nextPosition;

        emit BackerMilestoneVoteCast(roundId, stage, msg.sender, approved, weight);
    }

    /**
     * @notice Resolves a V2.3 milestone after its full review window has ended.
     * @dev Anyone may finalize. Silence never releases funds: missing quorum enters a
     *      seven-day grace period, then cancels the remaining grant escrow.
     */
    function finalizeBackerMilestone(uint256 roundId, uint8 stage) external nonReentrant whenNotPaused {
        _finalizeBackerMilestone(roundId, stage);
    }

    /* ========== VIEW FUNCTIONS ========== */

    /**
     * @notice Previews the milestone schedule for a settled winning pledge.
     * @dev The protocol fee is excluded because FundingPool holds it apart from grant escrow.
     */
    function previewGrant(uint256 roundId, uint256 ideaId)
        external
        view
        returns (
            uint256 totalGrant,
            uint256 initialPayout,
            uint256 inProcessPayout,
            uint256 completionPayout
        )
    {
        totalGrant = fundingPool.poolByRoundAndIdea(roundId, ideaId);
        initialPayout = (totalGrant * _initialPayoutPercent(votingSystem.isBackerMilestoneRound(roundId))) / 100;
        inProcessPayout = (totalGrant * IN_PROCESS_PAYOUT_PERCENT) / 100;
        completionPayout = totalGrant - initialPayout - inProcessPayout;
    }

    /**
     * @notice Checks if a grant can be claimed for a specific round
     * @dev Validates all conditions required for grant claiming
     * @param roundId The ID of the funding round
     * @return canClaim True if grant can be claimed
     * @return reason Human-readable reason if cannot claim
     */
    function canClaimGrant(uint256 roundId) 
        external 
        view 
        returns (
            bool canClaim, 
            string memory reason
        ) 
    {
        if (_grantPayouts[roundId].initialClaimed || fundingPool.isDistributed(roundId)) {
            return (false, "Grant already distributed");
        }

        (, , , uint256 endTime, , bool ended , , , ) = votingSystem.getRoundInfo(roundId);
        if (!ended) {
            return (false, "Round not ended");
        }

        if (block.timestamp >= endTime + GRANT_CLAIM_WINDOW) {
            return (false, "Grant claim window expired");
        }

        (uint256 winningIdeaId, ) = votingSystem.getRoundWinner(roundId);
        if (winningIdeaId == 0) {
            return (false, "No winner for this round");
        }

        if (ideaRegistry.getStatus(winningIdeaId) != IdeaStatus.WonVoting) {
            return (false, "Idea not in WonVoting status");
        }

        address author = ideaRegistry.getIdeaAuthor(winningIdeaId);
        if (author == address(0)) {
            return (false, "Invalid author address");
        }

        uint256 totalStake = fundingPool.poolByRoundAndIdea(roundId, winningIdeaId);
        if (totalStake == 0) {
            return (false, "No funds allocated to this idea");
        }

        return (true, "Grant can be claimed");
    }

    /**
     * @notice Gets the winning idea and author for a specific round
     * @param roundId The ID of the funding round
     * @return winningIdeaId The ID of the winning idea
     * @return author The address of the winning idea's author
     * @return ideaStatus The current status of the winning idea
     */
    function getRoundInfo(uint256 roundId) 
        external 
        view 
        returns (
            uint256 winningIdeaId,
            address author,
            IdeaStatus ideaStatus
        ) 
    {
        (winningIdeaId, ) = votingSystem.getRoundWinner(roundId);
        if (winningIdeaId != 0) {
            author = ideaRegistry.getIdeaAuthor(winningIdeaId);
            ideaStatus = ideaRegistry.getStatus(winningIdeaId);
        }
    }

    /**
     * @notice Returns payout tracking information for a round
     * @param roundId The ID of the funding round
     * @return ideaId Winning idea linked to the payout state
     * @return author Author entitled to receive payouts
     * @return totalGrant Total grant reserved for the author
     * @return released Total amount already released to the author
     * @return initialClaimed Whether the initial claim has already happened
     * @return inProcessPaid Whether the in-process tranche has been paid
     * @return completionPaid Whether the completion tranche has been paid
     */
    function getGrantPayout(uint256 roundId)
        external
        view
        returns (
            uint256 ideaId,
            address author,
            uint256 totalGrant,
            uint256 released,
            bool initialClaimed,
            bool inProcessPaid,
            bool completionPaid,
            uint256 initialClaimedAt,
            uint256 inProcessPaidAt,
            bool cancelled
        )
    {
        GrantPayout storage payout = _grantPayouts[roundId];
        return (
            payout.ideaId,
            payout.author,
            payout.totalGrant,
            payout.released,
            payout.initialClaimed,
            payout.inProcessPaid,
            payout.completionPaid,
            payout.initialClaimedAt,
            payout.inProcessPaidAt,
            payout.cancelled
        );
    }

    /**
     * @notice Returns the latest milestone request state for a round and stage
     * @param roundId The ID of the funding round
     * @param stage Milestone stage identifier
     * @return requestId Sequential identifier for the current request version
     * @return metadataURI Off-chain pointer to milestone proof payload
     * @return details Human-readable proof summary
     * @return submittedAt Timestamp when the request was submitted
     * @return lastRejectedAt Timestamp of the previous rejection for cooldown tracking
     * @return approvals Number of approvals collected so far
     * @return rejections Number of rejections collected so far
     * @return maxReviewers Reviewer cap configured for the selected stage
     * @return approvalThreshold Number of approvals required for acceptance
     * @return active Whether the request is still open for review
     */
    function getMilestoneRequest(uint256 roundId, uint8 stage)
        external
        view
        returns (
            uint256 requestId,
            string memory metadataURI,
            string memory details,
            uint256 submittedAt,
            uint256 lastRejectedAt,
            uint8 approvals,
            uint8 rejections,
            uint8 maxReviewers,
            uint8 approvalThreshold,
            bool active
        )
    {
        MilestoneRequest storage request = _milestoneRequests[roundId][stage];
        return (
            request.requestId,
            request.metadataURI,
            request.details,
            request.submittedAt,
            request.lastRejectedAt,
            request.approvals,
            request.rejections,
            request.maxReviewers,
            request.approvalThreshold,
            request.active
        );
    }

    /** @notice Returns the weighted state for the latest V2.3 milestone request. */
    function getBackerMilestoneTally(uint256 roundId, uint8 stage)
        external
        view
        returns (
            uint256 approveWeight,
            uint256 rejectWeight,
            uint256 approveBackerCount,
            uint256 graceDeadline
        )
    {
        MilestoneRequest storage request = _milestoneRequests[roundId][stage];
        BackerMilestoneTally storage tally = _backerMilestoneTallies[
            _backerVoteKey(roundId, stage, request.requestId)
        ];
        return (
            tally.approveWeight,
            tally.rejectWeight,
            tally.approveBackerCount,
            tally.graceDeadline
        );
    }

    /** @notice Returns the latest V2.3 proof package hash for a milestone stage. */
    function getBackerMilestoneProofHash(uint256 roundId, uint8 stage)
        external
        view
        returns (bytes32 proofHash)
    {
        MilestoneRequest storage request = _milestoneRequests[roundId][stage];
        return _backerMilestoneProofHashes[_backerVoteKey(roundId, stage, request.requestId)];
    }

