// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.20;

/** @notice Narrow execution-plan surface used by CommunityVotingModule. */
interface ICommunityMilestoneManager {
    function unresolvedPlanCount() external view returns (uint256);
    /** @notice Starts a plan from full financial support; the Manager excludes executor weight only from review. */
    function startExecutionPlan(uint256 proposalId, uint256 budget, uint256 totalSupportWeight, uint64 communityTime) external;

    /** @notice Whether a winning supporter's vote lock may be released. */
    function canReleaseReviewerLock(uint256 planId, address supporter) external view returns (bool);
}

// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.20;

/** @notice Narrow V3.1 execution-plan custody surface. */
interface ICommunityMilestoneTreasury {
    function reserveExecutionPlan(uint256 planId, uint256 amount) external;

    function releaseExecutionTranche(uint256 planId, address recipient, uint256 amount) external;

    function seedExecutionPlanRefund(uint256 planId, uint256 amount) external;

    function claimExecutionPlanRefund(uint256 planId, address recipient, uint256 amount) external;
}

// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.20;

/**
 * @notice Full financial winner-supporter snapshot consumed by CommunityMilestoneManager.
 * @dev CommunityVotingModule seals this at settlement. The Manager separately
 *      excludes the execution recipient from review, not from financial refunds.
 */
interface ICommunityMilestoneVoting {
    function milestoneVoterWeight(uint256 planId, address member) external view returns (uint256);

    function milestoneVoterCount(uint256 planId) external view returns (uint256);
}

// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.20;

import {CommunityTypes} from "../libraries/CommunityTypes.sol";

interface ICommunityProposalModule {
    function proposalCount() external view returns (uint256);
    function pendingValidationProposalCount() external view returns (uint256);
    function getProposal(uint256 proposalId) external view returns (CommunityTypes.Proposal memory);
    function getValidationEpoch(uint256 proposalId) external view returns (uint256);
    function getValidatorRewardEpoch(uint256 epochId) external view returns (CommunityTypes.ValidatorRewardEpoch memory);
    function isValidatorActiveForEpoch(uint256 epochId, address validator) external view returns (bool);

    function markBinaryVotingOpened(uint256 proposalId, uint64 communityTime, uint256 duration) external;
    function markRoundAssigned(uint256 proposalId, uint256 roundId) external;
    function recordBinaryVote(uint256 proposalId, CommunityTypes.VoteChoice choice, uint256 amount) external;
    function recordSlateVote(uint256 proposalId, uint256 amount) external;
    function settleBinaryProposal(uint256 proposalId, bool accepted) external;
    function settleSlateProposal(uint256 proposalId, bool won) external;
    function finalizeValidatorRewardEpoch(uint256 epochId, uint64 communityTime) external;
}

