pragma solidity ^0.8.20;

/**
 * @title CommunityTypes
 * @notice Shared V3 data shapes used by CommunityFactory, CommunityHub, and CommunityTreasury.
 * @dev This library is a namespace only. It has no storage, executable business logic, or access control.
 * 
 * @custom:version 2.1.0
 */
library CommunityTypes {
    uint256 internal constant MILESTONE_BPS_DENOMINATOR = 10_000;
    uint256 internal constant MILESTONE_QUORUM_BPS = 4_000;
    uint256 internal constant MILESTONE_APPROVAL_BPS = 6_667;
    uint256 internal constant MILESTONE_MIN_APPROVER_SHARE_BPS = 300;
    uint256 internal constant MILESTONE_MIN_UNIQUE_APPROVERS = 3;

    /**
     * @notice Lifecycle state of a community.
     * @dev Variants:
     * - Active: community accepts normal governance and treasury actions.
     * - Paused: new governance actions are blocked while previously earned claims remain available.
     * - Archived: community is permanently closed to new governance activity.
     */
    enum CommunityStatus {
        Active,
        Paused,
        Archived
    }

    /**
     * @notice Identifies which proposal lane owns a proposal.
     * @dev Variants:
     * - Admin: proposal was created by a community-local admin.
     * - Member: proposal was submitted by an active community member.
     */
    enum ProposalOrigin {
        Admin,
        Member
    }

    /**
     * @notice Voting mechanism assigned to a proposal.
     */
    enum ProposalMode {
        Binary,
        Slate
    }

    /**
     * @notice Lifecycle state for the binary-proposal MVP.
     * @dev Variants:
     * - PendingValidation: member proposal is awaiting validator decisions.
     * - RejectedByValidators: member proposal failed its validator gate.
     * - ApprovedForVoting: proposal is eligible for an admin to open voting.
     * - InVoting: members may currently commit stake to YES or NO.
     * - Accepted: YES received strictly more stake than NO.
     * - Rejected: NO received at least as much stake as YES.
     * - Settled: treasury settlement for the terminal vote outcome is complete.
     */
    enum ProposalStatus {
        PendingValidation,
        RejectedByValidators,
        ApprovedForVoting,
        ApprovedForRound,
        InVoting,
        InRoundVoting,
        Accepted,
        Rejected,
        WonRound,
        LostRound,
        Settled
    }

    /**
     * @notice A member's side in binary voting.
     * @dev Variants:
     * - None: no vote was recorded for the member and proposal.
     * - Yes: member committed stake in support of the proposal.
     * - No: member committed stake against the proposal.
     */
    enum VoteChoice {
        None,
        Yes,
        No
    }

    /**
     * @notice Describes a security-sensitive action that requires local Admin quorum.
     * @dev Admin quorum protects Community control-plane changes as well as Treasury withdrawals.
     * - Pause/Unpause: changes the Community governance clock state.
     * - Archive: permanently closes governance once all fund-bearing flows are resolved.
     * - AddAdmin/RemoveAdmin: changes the local Treasury control set through a quorum-approved request.
     * - AddValidator/RemoveValidator: changes the member-proposal review set.
     * - CancelWithdrawal: releases a Treasury withdrawal reservation after Admin quorum.
     */
    enum AdminActionType {
        Pause,
        Unpause,
        Archive,
        AddAdmin,
        RemoveAdmin,
        AddValidator,
        RemoveValidator,
        CancelWithdrawal
    }

    /**
     * @notice One immutable-intent, quorum-approved Community control-plane request.
     * @dev Approval membership is stored separately in CommunityHub to avoid copying mappings.
     * @dev Fields:
     * - action: protected action to execute after quorum.
     * - target: role recipient or role holder for role-management actions; zero otherwise.
     * - value: Treasury withdrawal request ID for CancelWithdrawal; zero otherwise.
     * - expiresAt: Community-clock deadline after which the request cannot execute.
     * - approvalCount: recorded Admin approvals, including the proposer.
     * - executed: whether the requested state change has completed.
     */
    struct AdminActionRequest {
        AdminActionType action;
        address target;
        uint256 value;
        uint64 expiresAt;
        uint256 approvalCount;
        bool executed;
    }

    /**
     * @notice Per-community configuration selected when the community is created.
     * @dev USDC values use the asset's native units. Arc USDC uses 6 decimals.
     * @dev Fields:
     * - name: display name shown to community members.
     * - metadataURI: offchain metadata describing the community.
     * - usdc: USDC-compatible asset used by all local flows.
     * - globalBertReserve: existing BERT reserve receiver for protocol-level inflows.
     * - initialAdmins: initial local admin addresses.
     * - initialValidators: initial local validator addresses, disjoint from admins.
     * - entryStakeUSDC: minimum refundable USDC stake required to join.
     * - proposalBondUSDC: USDC bond required for a member proposal.
     * - voteMinStakeUSDC: minimum USDC stake required for one vote.
     * - membershipExitCooldown: minimum delay between exit request and finalization.
     * - validatorApprovalThreshold: approvals required to pass member-proposal validation.
     * - adminApprovalThreshold: approvals required to execute a treasury withdrawal.
     * - binaryRejectionFeeBps: NO-side fee charged on a rejected proposal, in basis points.
     * - validatorRewardShareBps: YES settlement share reserved for active validators, in basis points.
     * - validationWindow: duration of the member-proposal validation period.
     * - binaryVotingDuration: duration of binary voting.
     * - roundVotingDuration: duration of slate round voting.
     * - validatorRewardEpoch: duration of one validator reward epoch.
     * - validatorActiveThresholdBps: minimum validation-case participation, in basis points.
     * - validatorProposalPointsThreshold: winning member proposals required before validator nomination.
     * - executionRecipient: immutable Community administration/team wallet receiving approved tranches.
     * - milestoneReviewDuration: pause-adjusted duration of one supporter milestone review.
     * - milestoneProofDuration: pause-adjusted deadline for submitting each milestone proof.
     */
    struct CommunityConfig {
        string name;
        string metadataURI;
        address usdc;
        address globalBertReserve;
        address[] initialAdmins;
        address[] initialValidators;
        uint256 entryStakeUSDC;
        uint256 proposalBondUSDC;
        uint256 voteMinStakeUSDC;
        uint256 membershipExitCooldown;
        uint256 validatorApprovalThreshold;
        uint256 adminApprovalThreshold;
        uint256 binaryRejectionFeeBps;
        uint256 validatorRewardShareBps;
        uint256 validationWindow;
        uint256 binaryVotingDuration;
        uint256 roundVotingDuration;
        uint256 validatorRewardEpoch;
        uint256 validatorActiveThresholdBps;
        uint256 validatorProposalPointsThreshold;
        address executionRecipient;
        uint64 milestoneReviewDuration;
        uint64 milestoneProofDuration;
    }

    /**
     * @notice Membership state maintained by CommunityHub for one account.
     * @dev Fields:
     * - active: whether the member can currently propose and vote.
     * - joinedAt: timestamp at which membership became active.
     * - exitRequestedAt: timestamp at which the member requested exit, or zero.
     * - membershipStake: refundable USDC stake held in CommunityTreasury.
     * - proposalPoints: winning member-proposal points earned by this account.
     */
    struct MemberInfo {
        bool active;
        uint64 joinedAt;
        uint64 exitRequestedAt;
        uint256 membershipStake;
        uint256 proposalPoints;
    }

    /**
     * @notice Onchain metadata and lifecycle state for one binary or slate proposal.
     * @dev Validator choices and voter choices live in mappings on CommunityHub, not in this struct.
     * @dev Fields:
     * - creator: address that created the proposal.
     * - origin: admin or member proposal lane.
     * - mode: binary YES/NO or slate-round choice.
     * - status: current lifecycle status.
     * - title: short proposal title.
     * - description: proposal body or summary.
     * - metadataURI: offchain proposal metadata.
     * - createdAt: proposal creation timestamp.
     * - validationDeadline: validation cutoff for a member proposal.
     * - votingStartedAt: binary voting start timestamp.
     * - votingDeadline: binary voting cutoff timestamp.
     * - bondAmount: proposal bond held in CommunityTreasury.
     * - yesVotes: aggregate YES stake.
     * - noVotes: aggregate NO stake.
     * - approvalCount: validator approvals.
     * - rejectionCount: validator rejections.
     * - assignedRoundId: slate round containing this proposal, if any.
     * - roundVotes: USDC votes assigned to this proposal in its slate round.
     * - accepted: whether YES won the binary vote.
     * - settled: whether Treasury settled the voting escrow.
     */
    struct Proposal {
        address creator;
        ProposalOrigin origin;
        ProposalMode mode;
        ProposalStatus status;
        string title;
        string description;
        string metadataURI;
        uint64 createdAt;
        uint64 validationDeadline;
        uint64 votingStartedAt;
        uint64 votingDeadline;
        uint256 bondAmount;
        uint256 yesVotes;
        uint256 noVotes;
        uint256 approvalCount;
        uint256 rejectionCount;
        uint256 assignedRoundId;
        uint256 roundVotes;
        bool accepted;
        bool settled;
    }

    /**
     * @notice One single-choice slate voting round.
     * @dev Fields:
     * - origin: proposal lane permitted in the round.
     * - startTime: community-clock timestamp when voting starts.
     * - endTime: community-clock timestamp when voting ends.
     * - totalVotes: USDC escrowed across all choices.
     * - winningProposalId: first proposal with the highest vote total.
     * - winningVotes: vote total of the selected winner.
     * - settled: whether Treasury routed the full round escrow.
     */
    struct CommunityRound {
        ProposalOrigin origin;
        uint64 startTime;
        uint64 endTime;
        uint256 totalVotes;
        uint256 winningProposalId;
        uint256 winningVotes;
        bool settled;
    }

    /**
     * @notice Accounting snapshot for one validator-reward epoch.
     * @dev Per-validator participation and claims are stored in mappings in CommunityHub and CommunityTreasury.
     * @dev Fields:
     * - startTime: inclusive timestamp at which validator activity starts counting.
     * - endTime: exclusive timestamp at which the epoch ends.
     * - availableValidationCases: cases available to validators during the epoch.
     * - rewardAmount: USDC reward pool allocated to the epoch.
     * - activeValidatorCount: validators that met the participation threshold.
     * - finalized: whether equal per-validator rewards have been calculated.
     */
    struct ValidatorRewardEpoch {
        uint64 startTime;
        uint64 endTime;
        uint256 availableValidationCases;
        uint256 rewardAmount;
        uint256 activeValidatorCount;
        bool finalized;
    }

    /**
     * @notice A withdrawal proposal from the community execution balance.
     * @dev Fields:
     * - to: USDC recipient after quorum execution.
     * - createdBy: admin that created the request.
     * - createdAt: request creation timestamp.
     * - amount: USDC amount reserved for the request.
     * - approvalCount: number of admin approvals recorded.
     * - reason: human-readable execution reason.
     * - metadataURI: offchain evidence or implementation metadata.
     * - executed: whether USDC has been transferred.
     * - cancelled: whether the reservation has been released.
     */
    struct WithdrawalRequest {
        address to;
        address createdBy;
        uint64 createdAt;
        uint256 amount;
        uint256 approvalCount;
        string reason;
        string metadataURI;
        bool executed;
        bool cancelled;
    }

    /**
     * @notice Immutable deployment record registered by CommunityFactory.
     * @dev Fields:
     * - creator: account that created the community and its initial admin.
     * - hub: CommunityHub that stores governance state.
     * - treasury: CommunityTreasury that holds the community's USDC.
     * - createdAt: block timestamp at which Factory registered the deployment.
     */
    struct CommunityDeployment {
        address creator;
        address hub;
        address treasury;
        uint64 createdAt;
    }

    /** @notice V3.1 lifecycle for the execution budget of a settled winner. */
    enum ExecutionPlanStatus {
        None,
        AwaitingProof,
        Reviewing,
        CorrectionCooldown,
        GraceReview,
        Completed,
        Failed,
        AwaitingTranche
    }

    enum MilestoneReviewChoice {
        None,
        Approve,
        Reject
    }

    /** @notice Immutable payment schedule and mutable review state for one winning proposal. */
    struct ExecutionPlan {
        uint256 proposalId;
        uint256 totalBudget;
        /// @notice Review-quorum weight; patched Managers exclude the execution recipient.
        uint256 eligibleSupportWeight;
        uint256 releasedAmount;
        uint256 refundableAmount;
        uint64 proofDeadline;
        uint8 currentMilestone;
        ExecutionPlanStatus status;
    }

    /** @notice Per-stage aggregate review state. Detailed evidence remains off-chain. */
    struct MilestoneReview {
        uint64 openedAt;
        uint64 closesAt;
        uint64 correctionAvailableAt;
        uint256 approvingWeight;
        uint256 rejectingWeight;
        uint256 approvingAddresses;
        uint256 participatingAddresses;
        uint8 proofAttempts;
        bytes32 evidenceHash;
    }

    /** @notice Immutable terms and payment state for one Admin-authorized tranche. */
    struct ExecutionTranche {
        uint256 amount;
        uint64 readyAt;
        uint64 expiresAt;
        uint256 approvalThreshold;
        bool paid;
    }
}

