    // =============================================================
    //                 VOTING-MODULE SNAPSHOT WRITES
    // =============================================================


@notice Records one wallet's stake behind a proposal that may later win.
@dev The voting module calls this only when a wallet supports that
     proposal. The voting layer rejects the proposal author's vote.
     This financial ledger includes an execution recipient's contribution
     for refund rights. CommunityMilestoneManager separately excludes that
     wallet's weight and address from milestone review.
     Duplicate entries
     and changes after sealing are rejected to preserve a single source
     of truth for milestone-review eligibility.
@param planId Proposal ID that is a potential execution-plan ID.
@param supporter Wallet that cast a supporting vote for the proposal.
@param weight Stake weight captured when the winning-support vote was cast.
/
    function recordWinnerSupport(uint256 planId, address supporter, uint256 weight) external onlyVotingModule {
        require(planId != 0 && supporter != address(0) && weight != 0, "invalid support");
        require(!snapshotSealed[planId], "snapshot sealed");
        require(supportWeight[planId][supporter] == 0, "support already recorded");
        supportWeight[planId][supporter] = weight;
        recordedWeight[planId] += weight;
        supporterCount[planId] += 1;
        emit WinnerSupportRecorded(planId, supporter, weight);
    }


@notice Permanently freezes a winning proposal's financial supporter cohort.
@dev `expectedTotalWeight` must match all weights accumulated through
     `recordWinnerSupport`; this cross-check detects an inconsistent
     settlement before any execution budget is created.
@param planId Proposal ID selected as the settled winner.
@param expectedTotalWeight Final total support weight reported by voting settlement.
/

@notice Permanently freezes a winning proposal's financial supporter cohort.
@dev `expectedTotalWeight` must match all weights accumulated through
     `recordWinnerSupport`; this cross-check detects an inconsistent
     settlement before any execution budget is created.
@param planId Proposal ID selected as the settled winner.
@param expectedTotalWeight Final total support weight reported by voting settlement.
/
    function sealWinnerSnapshot(uint256 planId, uint256 expectedTotalWeight) external onlyVotingModule {
        require(planId != 0 && !snapshotSealed[planId], "snapshot unavailable");
        require(expectedTotalWeight != 0 && recordedWeight[planId] == expectedTotalWeight, "weight mismatch");
        snapshotSealed[planId] = true;
        emit WinnerSnapshotSealed(planId, expectedTotalWeight, supporterCount[planId]);
    }

    // =============================================================
    //                  WINNING-SUPPORT SNAPSHOT VIEWS
    // =============================================================


