pragma solidity ^0.8.18;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title IFundingPool
 * @notice Interface for FundingPool contract that manages USDC deposits and grant distributions
 * @dev Provides external function declarations and event definitions for the funding pool system
 */
interface IFundingPool {
    /* ========== REVENUE ERRORS AND EVENTS ========== */

    /// @notice Receiver identity or fee-share combination is invalid.
    error InvalidRevenuePolicy();
    /// @notice No proposed policy exists or its notice period has not elapsed.
    error RevenuePolicyNotReady();
    /// @notice The caller has insufficient earned revenue for the requested collection.
    error RevenueUnavailable();
    /// @notice A revenue-enabled pool cannot change the token backing historical entitlements.
    error RevenueAssetLocked();
    /// @notice Actual token custody is below the recorded total.
    /// @param accounted Recorded custody in token-native units.
    /// @param actual Observed token balance.
    error PoolBalanceShortfall(uint256 accounted, uint256 actual);
    /// @notice Reserve plus revenue exceeds recorded custody; reconciliation is required.
    error InvalidRevenueAccounting();
    /// @notice A revenue transfer did not credit the exact amount requested.
    error UnsupportedRevenueTransfer();

    /// @notice Announces a policy after which only future rounds can use the split.
    /// @param treasury Proposed revenue receiver; zero disables future revenue.
    /// @param shareBps Share of earned fees, not share of the pool balance.
    /// @param readyAt Earliest execution timestamp.
    event RevenuePolicyScheduled(address indexed treasury, uint256 shareBps, uint256 readyAt);
    /// @notice Cancels the outstanding proposal without changing current policy.
    event RevenuePolicyCancelled();
    /// @notice Activates an announced policy for future round snapshots.
    /// @param treasury New current receiver.
    /// @param shareBps Share of earned fees.
    event RevenuePolicyActivated(address indexed treasury, uint256 shareBps);
    /// @notice Fixes a round's receiver and fee share, including zero-share rounds.
    /// @param roundId Newly opened round.
    /// @param treasury Fixed receiver.
    /// @param shareBps Fixed share of earned fees.
    event FundingRoundRevenueSnapshotted(uint256 indexed roundId, address indexed treasury, uint256 shareBps);
    /// @notice Separates pledge-funded fees from fees on reserve-funded top-ups at settlement.
    /// @param roundId Settled round.
    /// @param eligibleFee Fee attributable to recorded winning pledges only.
    /// @param totalFee Total fee under the unchanged settlement rules.
    event FundingRoundRevenueBaseSet(uint256 indexed roundId, uint256 eligibleFee, uint256 totalFee);
    /// @notice Records an earned fee entitlement without making an external receiver call.
    /// @param roundId Source round.
    /// @param treasury Round-local receiver.
    /// @param amount Newly accrued entitlement.
    event ProtocolRevenueAccrued(uint256 indexed roundId, address indexed treasury, uint256 amount);
    /// @notice Records earned revenue actually paid to its receiver.
    /// @param treasury Caller and immutable destination of this collection.
    /// @param amount USDC paid.
    event ProtocolRevenueClaimed(address indexed treasury, uint256 amount);

    /* ========== EVENTS ========== */

    /**
     * @notice Emmited when contract was initialized
     * @param sender Address who initialized the contract
     */
    event FundingPoolInitialized(address sender);
    /**
     * @notice Emitted when funds are deposited into the pool
     * @param donor Address of the depositor
     * @param amount Amount of tokens deposited
     */
    event FundsDeposited(address indexed donor, uint256 amount);

    /**
     * @notice Emitted when funds are distributed to a winning idea
     * @param roundId Identifier of the funding round
     * @param ideaId Identifier of the winning idea
     * @param amount Amount of tokens distributed
     */
    event FundsDistributed(uint256 indexed roundId, uint256 indexed ideaId, uint256 amount);

    /**
     * @notice Emitted when the total pool balance is updated
     * @param newBalance New total balance of the pool
     */
    event PoolBalanceUpdated(uint256 newBalance);

    /// @notice Emitted when a funding round locks its success fee.
    event FundingRoundOpened(uint256 indexed roundId, uint256 feeBps);

    /// @notice Emitted when a voter escrows a refundable pledge for an idea.
    event PledgeRecorded(
        uint256 indexed roundId,
        uint256 indexed ideaId,
        address indexed voter,
        uint256 amount
    );

    /// @notice Emitted once a funding round selects its winner and fee outcome.
    event FundingRoundSettled(
        uint256 indexed roundId,
        uint256 indexed winningIdeaId,
        uint256 grossFunding,
        uint256 fee,
        uint256 netFunding
    );

    event FundingRoundFeeFinalized(uint256 indexed roundId, uint256 amount);
    event ProgressiveFundingRoundFeeStarted(uint256 indexed roundId);
    event FundingRoundFeeReleased(
        uint256 indexed roundId,
        uint256 amount,
        uint256 cumulativeTrancheBps
    );
    event UnvestedFundingRoundFeeRestored(uint256 indexed roundId, uint256 amount);
    event FundingRoundCancelled(uint256 indexed roundId, uint256 indexed winningIdeaId, uint256 restoredFee);
    event GrantRefundActivated(uint256 indexed roundId, uint256 indexed winningIdeaId, uint256 totalRefund);

    /// @notice Emitted when a losing or unsuccessful pledge is returned to its voter.
    event PledgeRefundClaimed(
        uint256 indexed roundId,
        uint256 indexed ideaId,
        address indexed voter,
        uint256 amount
    );

    /// @notice Emitted when the fee for future funding rounds is changed.
    event PledgeFeeUpdated(uint256 feeBps);

    /// @notice Emitted when a funded proposal's author bond is returned.
    event AuthorStakeReleased(uint256 indexed ideaId, address indexed author, uint256 amount);

    /**
     * @notice Emitted when the USDC token address is updated
     * @param newToken Address of the new USDC token contract
     */
    event GovernanceTokenUpdated(address indexed newToken);

    /**
     * @notice Emitted when the USDC token address is updated
     * @param newToken Address of the new USDC token contract
     */
    event UsdcUpdated(address indexed newToken);

    /**
     * @notice Emitted when the idea registry address is updated
     * @param newRegistry Address of the new idea registry contract
     */
    event IdeaRegistryUpdated(address indexed newRegistry);

    /**
     * @notice Emitted when protocol reserve is allocated to a round/idea
     * @param roundId Identifier of the funding round
     * @param ideaId Identifier of the idea receiving the allocation
     * @param amount Amount allocated from reserve
     */
    event ProtocolReserveAllocated(uint256 indexed roundId, uint256 indexed ideaId, uint256 amount);

    /**
     * @notice Emitted when author stake is deposited for a new idea
     * @param ideaId Identifier of the idea
     * @param author Address that supplied the stake
     * @param amount Amount staked
     */
    event AuthorStakeDeposited(uint256 indexed ideaId, address indexed author, uint256 amount);

    /**
     * @notice Emitted when an author's stake is moved into protocol reserve
     * @param ideaId Identifier of the idea
     * @param amount Amount slashed into reserve
     */
    event AuthorStakeSlashed(uint256 indexed ideaId, uint256 amount);

    /**
     * @notice Emitted when idea-specific round funds are moved into protocol reserve
     * @param roundId Identifier of the funding round
     * @param ideaId Identifier of the idea
     * @param amount Amount moved into reserve
     */
    event IdeaFundsReserved(uint256 indexed roundId, uint256 indexed ideaId, uint256 amount);

    /**
     * @notice Emitted when the Factory authorized to authenticate V3 Treasuries is updated
     * @param communityFactory BERT V3 CommunityFactory address
     */
    event CommunityFactoryUpdated(address indexed communityFactory);

    /**
     * @notice Emitted when a Factory's authority to authenticate V3 Treasury reserve callers changes.
     * @param communityFactory CommunityFactory registry address.
     * @param approved Whether the Factory can currently authenticate an active Treasury caller.
     */
    event CommunityFactoryApprovalUpdated(address indexed communityFactory, bool approved);

    /**
     * @notice Emitted when an active V3 Treasury contributes USDC to protocol reserve
     * @param communityTreasury Authenticated V3 Treasury that supplied the reserve capital
     * @param amount USDC amount routed to protocol reserve
     */
    event CommunityReserveReceived(address indexed communityTreasury, uint256 amount);

    /* ========== REVENUE FUNCTIONS ========== */

    /// @notice Announces a fee split for future rounds after a 48-hour delay.
    /// @param treasury Receiver bound to this pool and token, or zero to disable.
    /// @param shareBps Share of earned fees in basis points, not share of user funds.
    function scheduleRevenuePolicy(address treasury, uint256 shareBps) external;

    /// @notice Cancels the outstanding announcement; only Admin may call.
    function cancelRevenuePolicy() external;

    /// @notice Permissionlessly activates the announced policy after its delay.
    function executeRevenuePolicy() external;

    /// @notice Collects only the calling receiver's earned entitlement.
    /// @param amount Amount to send to the caller itself.
    function claimProtocolRevenue(uint256 amount) external;

    /**
     * @notice Reports recorded custody and limited accounting categories.
     * @return actual Actual token custody.
     * @return accounted Recorded custody, inclusive of reserve and revenue.
     * @return reserve Reserve available for protocol allocation, not team withdrawal.
     * @return revenue Earned but uncollected receiver entitlements.
     * @return otherFunds Combined bonds, pledges, grants, fee escrow and donations.
     * @return surplus Direct-transfer surplus not yet recorded.
     * @return shortfall Recorded custody not backed by actual tokens.
     */
    function getTreasuryAccounting() external view returns (
        uint256 actual, uint256 accounted, uint256 reserve, uint256 revenue,
        uint256 otherFunds, uint256 surplus, uint256 shortfall
    );

    /* ========== DEPOSIT FUNCTIONS ========== */

    /**
     * @notice Deposits USDC into the funding pool
     * @dev Transfers tokens from caller to contract, updates donor balance
     * @param amount Amount of tokens to deposit
     */
    function deposit(uint256 amount) external;

    /**
     * @notice Pulls and accounts for USDC routed from an active BERT V3 CommunityTreasury
     * @dev The amount increases protocol reserve, not donor balances
     * @param amount USDC amount in token-native units
     */
    function receiveCommunityReserve(uint256 amount) external;

    /**
     * @notice Records the legacy primary V3 Factory and adds it to the Factory allowlist.
     * @param communityFactory V3 CommunityFactory address
     */
    function setCommunityFactory(address communityFactory) external;

    /**
     * @notice Adds or revokes a V3 Factory used to authenticate CommunityTreasury callers.
     * @param communityFactory V3 CommunityFactory address.
     * @param approved Whether the Factory may authenticate reserve callers.
     */
    function setCommunityFactoryApproval(address communityFactory, bool approved) external;

    /**
     * @notice Reports whether a Factory is approved to authenticate CommunityTreasury callers.
     * @param communityFactory V3 CommunityFactory address.
     * @return True when the Factory is allowlisted.
     */
    function isCommunityFactoryApproved(address communityFactory) external view returns (bool);

    /**
     * @notice Deposits author stake for an idea directly from the author
     * @dev Can only be called by the IdeaRegistry contract
     * @param from Author address that supplies the stake
     * @param ideaId ID of the idea
     * @param amount Amount of tokens to stake
     */
    function depositAuthorStakeFrom(address from, uint256 ideaId, uint256 amount) external;

    /// @notice Records one voter's refundable pledge for a funding round.
    function recordPledgeFrom(
        address from,
        uint256 roundId,
        uint256 ideaId,
        uint256 amount
    ) external;

    /// @notice Opens a pledge ledger before voting starts.
    function openFundingRound(uint256 roundId) external;

    /// @notice Settles a pledge round and holds the successful-round fee in escrow.
    function settleFundingRound(uint256 roundId, uint256 winningIdeaId) external;

    /// @notice Moves a successful round's pending fee to protocol reserve after grant claim.
    function finalizeFundingRoundFee(uint256 roundId) external;

    /** @notice Starts progressive fee vesting for a V2.3 backer-governed grant. */
    function beginProgressiveFundingRoundFee(uint256 roundId) external;

    /**
     * @notice Releases the fee earned by completed grant tranches up to a cumulative share.
     * @param roundId Funding round identifier
     * @param cumulativeTrancheBps Cumulative completed net-grant share in basis points
     */
    function releaseProgressiveFundingRoundFee(uint256 roundId, uint256 cumulativeTrancheBps) external;

    /// @notice Cancels an unclaimed winning grant and restores its fee for full refunds.
    function cancelUnclaimedFundingRound(uint256 roundId) external;

    /// @notice Opens pro-rata refunds for the unspent balance of an expired grant.
    function activateGrantRefund(uint256 roundId) external;

    /// @notice Returns a losing or unsuccessful pledge to its original voter.
    function claimPledgeRefund(uint256 roundId) external returns (uint256 amount);

    /// @notice Returns the net grant amount produced by a gross pledge total.
    function previewNetFunding(uint256 grossAmount) external view returns (uint256);

    /// @notice Returns a round's net grant amount using its immutable fee snapshot.
    function previewRoundNetFunding(uint256 roundId, uint256 grossAmount) external view returns (uint256);

    /// @notice Returns whether the funding round is settled and its selected winner.
    function getFundingRoundSettlement(uint256 roundId)
        external
        view
        returns (bool opened, bool settled, uint256 winningIdeaId);

    /// @notice Returns a voter's pledge and refund state for one round.
    function getPledge(uint256 roundId, address voter)
        external
        view
        returns (uint256 ideaId, uint256 amount, bool refundClaimed);

    /// @notice Returns the gross pledge total behind a settled winning grant.
    function winningGrossPledgeByRound(uint256 roundId) external view returns (uint256);

    /// @notice Configures the fee applied only to successful pledge rounds.
    function setPledgeFeeBps(uint256 feeBps) external;

    /// @notice One-time proxy-upgrade initializer for conditional-pledge fee configuration.
    function initializeConditionalPledges(uint256 initialFeeBps) external;

    /* ========== DISTRIBUTION FUNCTIONS ========== */

    /**
     * @notice Distributes funds to a winning idea
     * @dev Can only be called by addresses with GRANT_ROLE
     * @param roundId Grant round identifier
     * @param ideaId Winning idea identifier
     * @param amount Amount to distribute
     */
    function distributeFunds(
        uint256 roundId,
        uint256 ideaId,
        uint256 amount
    ) external;

    /**
     * @notice Slashes an author's locked idea stake into protocol reserve
     * @dev Can only be called by the IdeaRegistry contract
     * @param ideaId ID of the rejected idea
     */
    function slashAuthorStakeToReserve(uint256 ideaId) external;

    /// @notice Returns a successful proposal author's bond when its grant begins.
    function releaseAuthorStakeToAuthor(uint256 ideaId) external;

    /* ========== VIEW FUNCTIONS ========== */

    /**
     * @notice Returns the total number of distributions made
     * @return count Number of distribution records
     */
    function getDistributionCount() external view returns (uint256);

    /**
     * @notice Returns distribution details by index
     * @param index Position in distributionHistory array
     * @return roundId Grant round identifier
     * @return ideaId Winning idea identifier
     * @return amount Distributed amount
     * @return distributedAt Distribution timestamp
     */
    function getDistribution(uint256 index) external view returns (
        uint256 roundId,
        uint256 ideaId,
        uint256 amount,
        uint256 distributedAt
    );

